import smbus2 as smbus, time, sys
bus = smbus.SMBus(1)
addr = 0x48
CONFIG_OS_START = 0x8000
CONFIG_MUX_AIN0P_GNDN = 0x4000
CONFIG_FSR_4V096 = 0x0200
CONFIG_MODE_SINGLE = 0x0100
CONFIG_DATA_RATE_128SPS = 0x0080
CONFIG_COMP_QUE_DISABLE = 0x0003
DEVICE_REG_CONVERSION = 0x00
DEVICE_REG_CONFIG = 0x01
def swap(a):
    return ((a&0xff00)>>8)|((a&0x00ff)<<8)
def readAdc(c):
    config = CONFIG_OS_START | CONFIG_MUX_AIN0P_GNDN | (c<<12) | CONFIG_FSR_4V096 | CONFIG_MODE_SINGLE | CONFIG_DATA_RATE_128SPS | CONFIG_COMP_QUE_DISABLE
    bus.write_word_data(addr, DEVICE_REG_CONFIG, swap(config))
    while True:
        if swap(bus.read_word_data(addr, DEVICE_REG_CONFIG)) & CONFIG_OS_START:
            time.sleep(0.001)
        else:
            return swap(bus.read_word_data(addr, DEVICE_REG_CONVERSION))
try:
    while True:
        v = [readAdc(i) for i in range(4)]
        print(','.join(f'{i:05d}' for i in v))
        time.sleep(0.05)
except KeyboardInterrupt:
    sys.exit(0)

