#!/usr/bin/python

import time
import logging
import signal
import sys
from functools import partial

try:
    import smbus2 as smbus
except ImportError:
    try:
        import smbus as smbus
    except ImportError:
        print("Error: Could not import smbus. Please install smbus2 or smbus.")
        sys.exit(1)


# Constants for ADS1015 register addresses and configuration bits
ADS1015_DEFAULT_ADDRESS = 0x48
ADS1015_IC_DEFAULT_ADDRESS = 0x40
ADS1015_POINTER_CONVERT = 0x00
ADS1015_POINTER_CONFIG = 0x01
ADS1015_POINTER_LOW_THRESHOLD = 0x02
ADS1015_POINTER_HIGH_THRESHOLD = 0x03

# Configuration register bits and masks (see datasheet for details)
ADS1015_CONFIG_OS_START = 0x8000
ADS1015_CONFIG_OS_PERFORMING_CONVERSION = 0x0000
ADS1015_CONFIG_MUX_DIFF_0_1 = 0x0000
ADS1015_CONFIG_MUX_DIFF_0_3 = 0x1000
ADS1015_CONFIG_MUX_DIFF_1_3 = 0x2000
ADS1015_CONFIG_MUX_DIFF_2_3 = 0x3000
ADS1015_CONFIG_MUX_SINGLE_0 = 0x4000
ADS1015_CONFIG_MUX_SINGLE_1 = 0x5000
ADS1015_CONFIG_MUX_SINGLE_2 = 0x6000
ADS1015_CONFIG_MUX_SINGLE_3 = 0x7000
ADS1015_CONFIG_PGA_6_144V = 0x0000
ADS1015_CONFIG_PGA_4_096V = 0x0200
ADS1015_CONFIG_PGA_2_048V = 0x0400
ADS1015_CONFIG_PGA_1_024V = 0x0600
ADS1015_CONFIG_PGA_0_512V = 0x0800
ADS1015_CONFIG_PGA_0_256V = 0x0A00
ADS1015_CONFIG_MODE_SINGLE_SHOT = 0x0100
ADS1015_CONFIG_MODE_CONTINUOUS = 0x0000
ADS1015_CONFIG_DR_128SPS = 0x0000  # ADS1015 only
ADS1015_CONFIG_DR_250SPS = 0x0020
ADS1015_CONFIG_DR_490SPS = 0x0040
ADS1015_CONFIG_DR_920SPS = 0x0060
ADS1015_CONFIG_DR_1600SPS = 0x0080
ADS1015_CONFIG_DR_2400SPS = 0x00A0
ADS1015_CONFIG_DR_3300SPS = 0x00C0
ADS1015_CONFIG_COMP_MODE_TRADITIONAL = 0x0000
ADS1015_CONFIG_COMP_MODE_WINDOW = 0x0010
ADS1015_CONFIG_COMP_POL_ACTIVE_LOW = 0x0000
ADS1015_CONFIG_COMP_POL_ACTIVE_HIGH = 0x0008
ADS1015_CONFIG_COMP_LATCHING_DISABLED = 0x0000
ADS1015_CONFIG_COMP_LATCHING_ENABLED = 0x0004
ADS1015_CONFIG_COMP_QUE_DISABLE = 0x0003
ADS1015_CONFIG_COMP_QUE_1_CONV = 0x0000
ADS1015_CONFIG_COMP_QUE_2_CONV = 0x0001
ADS1015_CONFIG_COMP_QUE_4_CONV = 0x0002
ADS1015_CONFIG_COMP_QUE_ALL_CONV = 0x0003


logger = logging.getLogger(__name__)


def _validate_channel(channel):
    """Validate channel number."""
    if not 0 <= channel <= 3:
        raise ValueError("Invalid channel specified: {}".format(channel))


def _validate_pga(pga):
    """Validate programmable gain amplifier value."""
    allowed_pga = (6144, 4096, 2048, 1024, 512, 256)
    if pga not in allowed_pga:
        raise ValueError("Invalid PGA specified: {}".format(pga))


def _validate_sps(sps):
    """Validate samples per second."""
    allowed_sps = (128, 250, 490, 920, 1600, 2400, 3300)  # ADS1015 allowed SPS
    if sps not in allowed_sps:
        raise ValueError("Invalid SPS specified: {}".format(sps))


def _build_config(channel, pga, sps, mode, active_low, traditional_mode, latching, num_readings):
    """Build the configuration register value."""

    _validate_channel(channel)
    _validate_pga(pga)
    _validate_sps(sps)

    if channel == 0:
        mux_config = ADS1015_CONFIG_MUX_SINGLE_0
    elif channel == 1:
        mux_config = ADS1015_CONFIG_MUX_SINGLE_1
    elif channel == 2:
        mux_config = ADS1015_CONFIG_MUX_SINGLE_2
    else:
        mux_config = ADS1015_CONFIG_MUX_SINGLE_3

    # Determine PGA config
    if pga == 6144:
        pga_config = ADS1015_CONFIG_PGA_6_144V
    elif pga == 4096:
        pga_config = ADS1015_CONFIG_PGA_4_096V
    elif pga == 2048:
        pga_config = ADS1015_CONFIG_PGA_2_048V
    elif pga == 1024:
        pga_config = ADS1015_CONFIG_PGA_1_024V
    elif pga == 512:
        pga_config = ADS1015_CONFIG_PGA_0_512V
    else:
        pga_config = ADS1015_CONFIG_PGA_0_256V

    if mode == "single":
        mode_config = ADS1015_CONFIG_MODE_SINGLE_SHOT
    else:
        mode_config = ADS1015_CONFIG_MODE_CONTINUOUS

    if traditional_mode:
        comp_mode_config = ADS1015_CONFIG_COMP_MODE_TRADITIONAL
    else:
        comp_mode_config = ADS1015_CONFIG_COMP_MODE_WINDOW

    if active_low:
        comp_pol_config = ADS1015_CONFIG_COMP_POL_ACTIVE_LOW
    else:
        comp_pol_config = ADS1015_CONFIG_COMP_POL_ACTIVE_HIGH

    if latching:
        comp_latch_config = ADS1015_CONFIG_COMP_LATCHING_ENABLED
    else:
        comp_latch_config = ADS1015_CONFIG_COMP_LATCHING_DISABLED

    if num_readings == 1:
        comp_queue_config = ADS1015_CONFIG_COMP_QUE_DISABLE
    elif num_readings == 2:
        comp_queue_config = ADS1015_CONFIG_COMP_QUE_1_CONV
    elif num_readings == 4:
        comp_queue_config = ADS1015_CONFIG_COMP_QUE_2_CONV
    else:
        comp_queue_config = ADS1015_CONFIG_COMP_QUE_4_CONV

    config = (
        ADS1015_CONFIG_OS_START  # Start a conversion
        + mux_config  # Select the channel
        + pga_config  # Set the PGA
        + ADS1015_CONFIG_DR_1600SPS # Fix SPS to max for ADS1015
        + mode_config  # Set the conversion mode
        + comp_mode_config  # Set the comparator mode
        + comp_pol_config  # Set the comparator polarity
        + comp_latch_config  # Set the comparator latching
        + comp_queue_config  # Set the comparator queue
    )

    return config, sps



def _twos_complement(val, bits=12):
    """Convert unsigned integer to signed integer (two's complement)."""
    if (val & (1 << (bits - 1))) != 0:
        val = val - (1 << bits)
    return val


def _read_conversion_result(bus, address, sps):
    """Read the conversion result from the ADS1015."""
    try:
        result = bus.read_i2c_block_data(address, ADS1015_POINTER_CONVERT, 2)
    except OSError as e:
        logger.error("Error reading conversion result: {}".format(e))
        raise
    value = (result[0] << 8) | result[1]
    return _twos_complement(value, bits=12)



def _wait_for_conversion(sps):
    """Wait for the conversion to complete based on the SPS value."""
    if sps == 128:
        time.sleep(1.0 / 128)
    elif sps == 250:
        time.sleep(1.0 / 250)
    elif sps == 490:
        time.sleep(1.0 / 490)
    else:
        time.sleep(1.0 / sps)  # Generic wait for other allowed SPS values



class ADS1015:
    """Driver for the ADS1015 ADC."""

    def __init__(self, address=ADS1015_DEFAULT_ADDRESS, busnum=1, debug=False):
        """Initialize the ADS1015 driver."""
        self.address = address
        self.busnum = busnum
        self.debug = debug
        self.bus = smbus.SMBus(busnum)
        self._last_sps = 1600 # Default SPS


    def _log_debug(self, message):
        """Log debug message if enabled."""
        if self.debug:
            logger.debug(message)


    def verify(self):
        """Verify the ADS1015 is connected by reading the config register."""
        try:
            self.bus.read_word_data(self.address, ADS1015_POINTER_CONFIG)
            return True
        except OSError:
            return False


    def read_adc_single_ended(self, channel=0, pga=6144, sps=250):
        """Read a single-ended ADC value from the specified channel."""
        _validate_channel(channel)
        _validate_pga(pga)
        _validate_sps(sps)

        config, used_sps = _build_config(channel, pga, sps, "single", True, True, False, 1)
        self._last_sps = used_sps

        self._log_debug(
            "Reading single-ended channel {} with PGA {} SPS {}".format(
                channel, pga, sps
            )
        )

        try:
            # Write config register to start the conversion
            self.bus.write_word_data(self.address, ADS1015_POINTER_CONFIG, config)

            # Wait for conversion to complete
            _wait_for_conversion(used_sps)

            # Read the conversion result
            result = _read_conversion_result(self.bus, self.address, used_sps)
            return result

        except OSError as e:
            logger.error("Error reading ADC: {}".format(e))
            raise


    def start_continuous_conversion(self, channel=0, pga=6144, sps=250):
        """Start continuous conversion mode on the specified channel."""
        _validate_channel(channel)
        _validate_pga(pga)
        _validate_sps(sps)

        config, used_sps = _build_config(channel, pga, sps, "continuous", True, True, False, 1)
        self._last_sps = used_sps

        self._log_debug(
            "Starting continuous conversion on channel {} with PGA {} SPS {}".format(
                channel, pga, sps
            )
        )

        try:
            self.bus.write_word_data(self.address, ADS1015_POINTER_CONFIG, config)
        except OSError as e:
            logger.error("Error starting continuous conversion: {}".format(e))
            raise


    def get_last_conversion_results(self):
        """Get the last conversion result while in continuous mode."""
        try:
            result = _read_conversion_result(self.bus, self.address, self._last_sps)
            return result
        except OSError as e:
            logger.error("Error getting last conversion result: {}".format(e))
            raise


    def start_single_ended_comparator(
        self, channel, threshold_high, threshold_low, pga=6144, sps=250, active_low=True, traditional_mode=True, latching=False, num_readings=1
    ):
        """Start single-ended comparator mode on the specified channel."""
        _validate_channel(channel)
        _validate_pga(pga)
        _validate_sps(sps)

        config, used_sps = _build_config(
            channel, pga, sps, "single", active_low, traditional_mode, latching, num_readings
        )
        self._last_sps = used_sps

        self._log_debug(
            "Starting comparator on channel {} with high threshold {} and low threshold {}".format(
                channel, threshold_high, threshold_low
            )
        )

        try:
            # Write threshold values
            self.bus.write_word_data(
                self.address, ADS1015_POINTER_HIGH_THRESHOLD, threshold_high
            )
            self.bus.write_word_data(
                self.address, ADS1015_POINTER_LOW_THRESHOLD, threshold_low
            )

            # Write config register to start the conversion
            self.bus.write_word_data(self.address, ADS1015_POINTER_CONFIG, config)
        except OSError as e:
            logger.error("Error starting comparator: {}".format(e))
            raise


if __name__ == "__main__":
    logging.basicConfig(level=logging.DEBUG)

    adc = ADS1015(debug=True)
    if adc.verify():
        logger.info("ADS1015 found on bus {} at address {}".format(adc.busnum, adc.address))
    else:
        logger.error("ADS1015 not found on bus {} at address {}".format(adc.busnum, adc.address))
        sys.exit(1)

    try:
        value = adc.read_adc_single_ended(channel=0)
        logger.info("Channel 0: {}".format(value))
    except OSError:
        logger.error("Error reading channel 0")

    try:
        adc.start_continuous_conversion(channel=1)
        for _ in range(5):
            value = adc.get_last_conversion_results()
            logger.info("Channel 1 (Continuous): {}".format(value))
            time.sleep(0.1)
    except OSError:
        logger.error("Error reading channel 1 (Continuous)")

    try:
        adc.start_single_ended_comparator(channel=2, threshold_high=1000, threshold_low=500)
        logger.info("Comparator started on channel 2")
    except OSError:
        logger.error("Error starting comparator on channel 2")

