import RPi.GPIO as GPIO
import spidev
import time
import logging
import threading
import queue
import argparse
import sys

class SoundSensor:
    """
    A class to represent a sound sensor connected to a Raspberry Pi.
    Supports both digital and analog sound sensors.
    """

    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins=None, channels=None, spi_speed=1000000, log_queue=None):
        """
        Initializes the SoundSensor object.

        Args:
            sensor_id (str): A unique identifier for the sensor.
            sensor_type (str): The type of sensor ("digital" or "analog").
            threshold (int): The threshold value for sound detection (for analog sensors).
            sample_rate (int): The sampling rate in Hz.
            gpio_pins (list): A list of GPIO pins to use (for digital sensors).
            channels (list): A list of MCP3008 channels to use (for analog sensors).
            spi_speed (int): The SPI clock speed in Hz.
            log_queue (queue.Queue): A queue to send log messages to.
        """
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.spi = None
        self.running = False
        self.thread = None

        if self.sensor_type == "analog":
            try:
                self.spi = spidev.SpiDev()
                self.spi.open(0, 0)  # Bus 0, Device 0
                self.spi.max_speed_hz = self.spi_speed
            except Exception as e:
                self.log_error(f"Failed to initialize SPI: {e}")
                self.spi = None
        elif self.sensor_type == "digital":
            try:
                GPIO.setmode(GPIO.BCM)
                for pin in self.gpio_pins:
                    GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)  # Use pull-down resistors
            except Exception as e:
                self.log_error(f"Failed to initialize GPIO: {e}")
        else:
            self.log_error("Invalid sensor type. Must be 'digital' or 'analog'.")
            sys.exit(1)

    def log_error(self, message):
        """Logs an error message to the log queue."""
        if self.log_queue:
            self.log_queue.put((logging.ERROR, f"Sensor {self.sensor_id}: {message}"))
        else:
            logging.error(f"Sensor {self.sensor_id}: {message}")

    def log_info(self, message):
        """Logs an info message to the log queue."""
        if self.log_queue:
            self.log_queue.put((logging.INFO, f"Sensor {self.sensor_id}: {message}"))
        else:
            logging.info(f"Sensor {self.sensor_id}: {message}")

    def read_analog(self, channel):
        """Reads the analog value from the MCP3008 ADC."""
        try:
            adc = self.spi.xfer2([1, (8 + channel) << 4, 0])
            data = ((adc[1] & 3) << 8) + adc[2]
            return data
        except Exception as e:
            self.log_error(f"Error reading analog channel {channel}: {e}")
            return -1

    def read_digital(self, pin):
        """Reads the digital value from the GPIO pin."""
        try:
            return GPIO.input(pin)
        except Exception as e:
            self.log_error(f"Error reading digital pin {pin}: {e}")
            return -1

    def run(self):
        """Runs the sound detection loop in a separate thread."""
        self.running = True
        self.thread = threading.Thread(target=self._run_sensor)
        self.thread.daemon = True  # Allow the main thread to exit even if this thread is running
        self.thread.start()

    def _run_sensor(self):
        """Internal method to run the sound detection loop."""
        try:
            while self.running:
                if self.sensor_type == "analog":
                    for channel in self.channels:
                        adc_value = self.read_analog(channel)
                        if adc_value != -1 and adc_value >= self.threshold:
                            self.log_info(f"Sound detected on channel {channel} (ADC value: {adc_value})")
                            time.sleep(0.1)  # Debounce
                elif self.sensor_type == "digital":
                    for pin in self.gpio_pins:
                        digital_value = self.read_digital(pin)
                        if digital_value != -1 and digital_value == 1:
                            self.log_info(f"Sound detected on pin {pin} (GPIO value: {digital_value})")
                            time.sleep(0.1)  # Debounce
                time.sleep(1 / self.sample_rate)
        except Exception as e:
            self.log_error(f"Sensor thread error: {e}")
        finally:
            self.stop()

    def stop(self):
        """Stops the sound detection loop and cleans up resources."""
        self.running = False
        if self.thread and self.thread.is_alive():
            self.thread.join()
        if self.sensor_type == "analog" and self.spi:
            try:
                self.spi.close()
            except Exception as e:
                self.log_error(f"Error closing SPI: {e}")
        elif self.sensor_type == "digital":
            try:
                GPIO.cleanup()  # Clean up GPIO pins
            except Exception as e:
                self.log_error(f"Error cleaning up GPIO: {e}")
        self.log_info("Sensor stopped.")

def main():
    """Main function to parse arguments and start the sound sensors."""
    parser = argparse.ArgumentParser(description="Sound level monitoring system for Raspberry Pi.")
    parser.add_argument("--sensor_type", required=True, choices=["digital", "analog"], help="Type of sound sensor (digital or analog).")
    parser.add_argument("--threshold", type=int, help="Threshold value for sound detection (for analog sensors).")
    parser.add_argument("--sample_rate", type=int, default=10, help="Sampling rate in Hz.")
    parser.add_argument("--log_file", type=str, default="sound_monitor.log", help="Path to the log file.")
    parser.add_argument("--gpio_pins", type=str, help="Comma-separated list of GPIO pins to use (for digital sensors).")
    parser.add_argument("--channels", type=str, help="Comma-separated list of MCP3008 channels to use (for analog sensors).")
    parser.add_argument("--spi_speed", type=int, default=1000000, help="SPI clock speed in Hz.")
    parser.add_argument("--sensor_ids", type=str, required=True, help="Comma-separated list of sensor IDs.")

    args = parser.parse_args()

    # Configure logging
    logging.basicConfig(filename=args.log_file, level=logging.INFO,
                        format='%(asctime)s - %(levelname)s - %(message)s')

    # Parse GPIO pins and channels
    gpio_pins = [int(pin) for pin in args.gpio_pins.split(",")] if args.gpio_pins else None
    channels = [int(channel) for channel in args.channels.split(",")] if args.channels else None

    # Parse sensor IDs
    sensor_ids = args.sensor_ids.split(",")

    # Create a queue for log messages
    log_queue = queue.Queue()

    # Create and start sound sensors
    sensors = []
    for i, sensor_id in enumerate(sensor_ids):
        if args.sensor_type == "digital":
            if gpio_pins is None or len(gpio_pins) != len(sensor_ids):
                logging.error("Number of GPIO pins must match the number of sensor IDs for digital sensors.")
                sys.exit(1)
            sensor = SoundSensor(sensor_id, args.sensor_type, None, args.sample_rate, gpio_pins=[gpio_pins[i]], log_queue=log_queue)
        elif args.sensor_type == "analog":
            if channels is None or len(channels) != len(sensor_ids):
                logging.error("Number of channels must match the number of sensor IDs for analog sensors.")
                sys.exit(1)
            if args.threshold is None:
                logging.error("Threshold must be specified for analog sensors.")
                sys.exit(1)
            sensor = SoundSensor(sensor_id, args.sensor_type, args.threshold, args.sample_rate, channels=[channels[i]], spi_speed=args.spi_speed, log_queue=log_queue)
        sensors.append(sensor)
        sensor.run()

    # Log messages from the queue
    def log_worker():
        while True:
            try:
                level, message = log_queue.get(timeout=1)  # Wait for 1 second
                logging.log(level, message)
                log_queue.task_done()
            except queue.Empty:
                pass  # No messages, continue looping
            except Exception as e:
                logging.error(f"Error in log worker: {e}")
                break

    log_thread = threading.Thread(target=log_worker)
    log_thread.daemon = True
    log_thread.start()

    try:
        while True:
            time.sleep(1)  # Keep the main thread alive
    except KeyboardInterrupt:
        print("Stopping sensors...")
        for sensor in sensors:
            sensor.stop()
        log_queue.join()  # Wait for all log messages to be processed
        print("Exiting.")

if __name__ == "__main__":
    main()

