import subprocess
import RPi.GPIO as GPIO
import gpiozero
import picamera2
import paho.mqtt.client as mqtt
import adafruit_dht
import adafruit_mlx90614
import board
import busio

# Configure logging
logging.basicConfig(level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

class SecuritySystem:
    def __init__(self, config_file):
        self.config_file = config_file
        self.config = self.load_config()
        self.camera = None
        self.motion_queue = queue.Queue(maxsize=self.config['motion_queue_size'])
        self.motion_thread = None
        self.mqtt_client = None
        self.led = None
        self.dht_device = None
        self.mlx = None
        self.running = True
        self.last_motion_time = None
        self.motion_cooldown = self.config.get('motion_cooldown', 5)  # seconds
        self.motion_threshold = self.config.get('motion_threshold', 20) # Adjust as needed
        self.motion_sensitivity = self.config.get('motion_sensitivity', 0.5) # Adjust as needed
        self.motion_duration = self.config.get('motion_duration', 2) # seconds
        self.motion_alert_sent = False
        self.motion_alert_cooldown = self.config.get('motion_alert_cooldown', 60) # seconds
        self.last_motion_alert_time = None

        # Initialize GPIO if enabled
        if self.config.get('gpio_pin'):
            try:
                self.led = gpiozero.LED(self.config['gpio_pin'])
                logging.info(f"GPIO pin {self.config['gpio_pin']} initialized for LED.")
            except Exception as e:
                logging.error(f"Error initializing GPIO pin: {e}")
                self.led = None

        # Initialize DHT sensor if enabled
        if self.config.get('dht_pin'):
            try:
                self.dht_device = adafruit_dht.DHT22(board.D4) # Example using D4 pin
                logging.info(f"DHT sensor initialized on pin {self.config['dht_pin']}.")
            except Exception as e:
                logging.error(f"Error initializing DHT sensor: {e}")
                self.dht_device = None

        # Initialize MLX90614 sensor if enabled
        if self.config.get('mlx90614'):
            try:
                i2c = busio.I2C(board.SCL, board.SDA)
                self.mlx = adafruit_mlx90614.MLX90614(i2c)
                logging.info("MLX90614 sensor initialized.")
            except Exception as e:
                logging.error(f"Error initializing MLX90614 sensor: {e}")
                self.mlx = None

    def load_config(self):
        try:
            with open(self.config_file, 'r') as f:
                config = json.load(f)
            return config
        except FileNotFoundError:
            logging.error(f"Config file not found: {self.config_file}")
            exit(1)
        except json.JSONDecodeError:
            logging.error(f"Invalid JSON in config file: {self.config_file}")
            exit(1)

    def initialize_camera(self):
        try:
            self.camera = picamera2.Picamera2()
            config = self.camera.create_still_configuration(main={"size": (self.config['camera_resolution'][0], self.config['camera_resolution'][1])}, controls={"FrameRate": self.config['camera_framerate']})
            self.camera.configure(config)
            self.camera.start()
            time.sleep(2)  # Camera warm-up
            logging.info("Camera initialized successfully.")
        except Exception as e:
            logging.error(f"Error initializing camera: {e}")
            self.camera = None

    def initialize_mqtt(self):
        if self.config.get('mqtt_enabled'):
            try:
                self.mqtt_client = mqtt.Client()
                self.mqtt_client.on_connect = self.on_mqtt_connect
                self.mqtt_client.on_disconnect = self.on_mqtt_disconnect
                self.mqtt_client.on_message = self.on_mqtt_message
                self.mqtt_client.connect(self.config['mqtt_broker_address'], self.config['mqtt_broker_port'], 60)
                self.mqtt_client.loop_start()
                logging.info("MQTT client initialized and connected.")
            except Exception as e:
                logging.error(f"Error initializing MQTT client: {e}")
                self.mqtt_client = None

    def on_mqtt_connect(self, client, userdata, flags, rc):
        if rc == 0:
            logging.info("Connected to MQTT Broker!")
            if self.config.get('mqtt_topic_subscribe'):
                client.subscribe(self.config['mqtt_topic_subscribe'])
        else:
            logging.error(f"Failed to connect to MQTT Broker, return code {rc}")

    def on_mqtt_disconnect(self, client, userdata, rc):
        logging.warning("Disconnected from MQTT Broker.")

    def on_mqtt_message(self, client, userdata, msg):
        logging.info(f"Received message: {msg.topic} {msg.payload.decode()}")
        # Implement message handling logic here (e.g., trigger camera recording)

    def capture_frames(self):
        if not self.camera:
            logging.error("Camera not initialized. Cannot capture frames.")
            return

        try:
            while self.running:
                start_time = time.time()
                frame = self.camera.capture_array()
                try:
                    self.motion_queue.put(frame, timeout=1)  # Add frame to queue
                except queue.Full:
                    logging.warning("Motion queue is full. Dropping frame.")
                except Exception as e:
                    logging.error(f"Error adding frame to queue: {e}")

                elapsed_time = time.time() - start_time
                sleep_time = max(0, 1/self.config['camera_framerate'] - elapsed_time)
                time.sleep(sleep_time) # Control framerate
        except Exception as e:
            logging.error(f"Error in capture_frames: {e}")
        finally:
            logging.info("Capture frames thread stopped.")

    def detect_motion(self):
        if not self.camera:
            logging.error("Camera not initialized. Cannot detect motion.")
            return

        try:
            while self.running:
                try:
                    frame = self.motion_queue.get(timeout=1)
                    # Convert frame to grayscale (simplified motion detection)
                    gray_frame = frame.mean(axis=2)

                    # Calculate the difference between consecutive frames
                    if hasattr(self, 'previous_gray_frame'):
                        frame_diff = abs(gray_frame - self.previous_gray_frame)
