# Raspberry Pi script to monitor proximity sensors via PCF8574 I2C expander.
# Uses interrupt-driven approach for efficient sensor readings.

import time
import smbus2
from gpiozero import InputDevice
from functools import partial

# Configuration
PCF8574_ADDRESS = 0x20  # I2C address of the PCF8574
I2C_BUS_NUMBER = 1  # I2C bus number on Raspberry Pi
INTERRUPT_PIN = 17  # BCM GPIO pin connected to PCF8574's interrupt output

# Initialize I2C bus
try:
    i2c_bus = smbus2.SMBus(I2C_BUS_NUMBER)
except Exception as e:
    print(f"Error initializing I2C bus: {e}")
    exit(1)

# Initialize interrupt pin
interrupt = InputDevice(INTERRUPT_PIN, pull_up=True)

# Function to read sensor state from PCF8574
def read_sensor_state(bus, address):
    """Reads the current state of all 8 proximity sensors."""
    try:
        return bus.read_byte(address)
    except Exception as e:
        print(f"Error reading sensor state: {e}")
        return None

# Callback function for interrupt events
def proximity_callback(bus, address, sensor_count):
    """Handles interrupt events and prints obstacle detection status."""
    sensor_state = read_sensor_state(bus, address)
    if sensor_state is not None:
        for i in range(sensor_count):
            if (sensor_state & (1 << i)) == 0:  # Active-low signal
                print(f"Obstacle detected by sensor {i}")

# Main execution block
if __name__ == "__main__":
    try:
        # Partial function for callback with pre-filled arguments
        callback_with_args = partial(proximity_callback, i2c_bus, PCF8574_ADDRESS, 8)

        # Register interrupt event handler
        interrupt.when_falled = callback_with_args

        # Keep the script running to listen for interrupts
        while True:
            time.sleep(1)

    except KeyboardInterrupt:
        print("Script interrupted by user.")

    except Exception as e:
        print(f"An unexpected error occurred: {e}")

    finally:
        # Cleanup resources
        try:
            i2c_bus.close()
        except Exception as e:
            print(f"Error closing I2C bus: {e}")

        try:
            interrupt.close()
        except Exception as e:
            print(f"Error closing interrupt device: {e}")

        print("Script finished.")

