#!/usr/bin/env python3

import speech_recognition as sr
import RPi.GPIO as GPIO
import time
import datetime
import os
import signal
import sys
from picamera2 import Picamera2
import random

# Define GPIO pins
LIGHT_PIN = 17
DHT_PIN = 4

# Global variables
lights_on = False
camera = None
simulated_temperature = 25.0  # Initial simulated temperature

# Function to initialize GPIO
def initialize_gpio():
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LIGHT_PIN, GPIO.OUT)
        GPIO.output(LIGHT_PIN, GPIO.LOW)  # Ensure lights are off initially
        print("GPIO initialized successfully.")
        return True
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        return False

# Function to turn lights on
def turn_lights_on():
    global lights_on
    try:
        GPIO.output(LIGHT_PIN, GPIO.HIGH)
        lights_on = True
        print("Lights turned ON.")
    except Exception as e:
        print(f"Error turning lights on: {e}")

# Function to turn lights off
def turn_lights_off():
    global lights_on
    try:
        GPIO.output(LIGHT_PIN, GPIO.LOW)
        lights_on = False
        print("Lights turned OFF.")
    except Exception as e:
        print(f"Error turning lights off: {e}")

# Function to read temperature from DHT11 sensor
def read_temperature():
    try:
        import adafruit_dht
        dht_device = adafruit_dht.DHT11(DHT_PIN)
        temperature = dht_device.temperature
        if temperature is not None:
            return temperature
        else:
            print("Failed to read temperature from DHT11 sensor.")
            return None
    except ImportError:
        print("adafruit_dht library not found. Using simulated temperature.")
        return None
    except Exception as e:
        print(f"Error reading temperature: {e}")
        return None

# Function to capture image
def capture_image():
    global camera
    try:
        if camera is None:
            camera = Picamera2()
            camera.configure(camera.create_preview_configuration(main={"format": 'XRGB8888', "size": (640, 480)}))
            camera.start()

        timestamp = datetime.datetime.now().strftime("%Y-%m-%d_%H-%M-%S")
        filename = f"greenhouse_{timestamp}.jpg"
        camera.capture_file(filename)
        print(f"Image captured and saved as {filename}")
    except Exception as e:
        print(f"Error capturing image: {e}")

# Function to handle voice commands
def handle_voice_command(command):
    command = command.lower()
    if "turn on the lights" in command:
        turn_lights_on()
    elif "turn off the lights" in command:
        turn_lights_off()
    elif "what is the temperature" in command:
        temperature = read_temperature()
        if temperature is not None:
            print(f"The temperature is {temperature:.1f} degrees Celsius.")
        else:
            print("Could not read temperature.")
    elif "take a picture" in command:
        capture_image()
    else:
        print("Invalid command.")

# Function to listen for voice commands
def listen_for_commands():
    r = sr.Recognizer()
    mic = sr.Microphone()

    with mic as source:
        r.adjust_for_ambient_noise(source)  # Adjust for background noise
        print("Say 'Greenhouse' followed by a command...")

        while True:
            try:
                audio = r.listen(source, timeout=5)  # Listen for 5 seconds
                try:
                    # Use Google Web Speech API for voice recognition
                    command = r.recognize_google(audio)
                    print(f"You said: {command}")

                    if "greenhouse" in command.lower():
                        handle_voice_command(command)
                    else:
                        print("Wake word not detected.")

                except sr.UnknownValueError:
                    print("Could not understand audio")
                except sr.RequestError as e:
                    print(f"Could not request results from Google Speech Recognition service; {e}")

            except sr.WaitTimeoutError:
                print("No speech detected. Listening again...")
            except Exception as e:
                print(f"An unexpected error occurred: {e}")

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    print("Exiting program...")
    if camera:
        camera.close()
    GPIO.cleanup()
    sys.exit(0)

# Main function
def main():
    # Initialize GPIO
    gpio_initialized = initialize_gpio()

    # Set up signal handler for Ctrl+C
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Start listening for voice commands
    listen_for_commands()

if __name__ == "__main__":
    main()

