import cv2
import pyzbar.pyzbar as pyzbar
import csv
import datetime
import time
import os
import re

# Configuration
CAMERA_INDEX = 0  # Index of the USB camera
LOG_FILE = 'inventory_log.csv'
ERROR_LOG_FILE = 'error_log.txt'
CAMERA_ID = 'Camera 1'  # Fixed camera identifier

def log_error(message):
    """Logs an error message to the error log file with a timestamp."""
    timestamp = datetime.datetime.now().isoformat()
    try:
        with open(ERROR_LOG_FILE, 'a') as f:
            f.write(f"{timestamp} - ERROR: {message}\n")
    except Exception as e:
        print(f"Failed to write to error log: {e}")

def is_valid_item_id(item_id):
    """Validates that the item ID is a non-empty alphanumeric string."""
    return bool(re.match(r'^[a-zA-Z0-9]+$', item_id))

def log_to_csv(camera_id, item_id, capture_time):
    """Logs the camera ID, item ID, and capture time to the CSV file."""
    try:
        file_exists = os.path.isfile(LOG_FILE)
        with open(LOG_FILE, 'a', newline='') as csvfile:
            fieldnames = ['camera_id', 'item_id', 'capture_time']
            writer = csv.DictWriter(csvfile, fieldnames=fieldnames)

            if not file_exists:
                writer.writeheader()  # Write header only if the file is new

            writer.writerow({'camera_id': camera_id, 'item_id': item_id, 'capture_time': capture_time})
    except Exception as e:
        log_error(f"Failed to write to CSV: {e}")

def main():
    """Main function to capture images, decode QR codes, and log data."""
    try:
        cap = cv2.VideoCapture(CAMERA_INDEX)
        if not cap.isOpened():
            raise Exception(f"Could not open USB camera at index {CAMERA_INDEX}")

        while True:
            ret, frame = cap.read()
            if not ret:
                log_error("Failed to capture frame")
                time.sleep(0.2)
                continue

            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            decoded_objects = pyzbar.decode(gray)

            for obj in decoded_objects:
                item_id = obj.data.decode('utf-8')
                if is_valid_item_id(item_id):
                    capture_time = datetime.datetime.now().isoformat()
                    log_to_csv(CAMERA_ID, item_id, capture_time)
                    print(f"Item ID: {item_id}, Captured at: {capture_time}")
                else:
                    log_error(f"Invalid item ID: {item_id}")

            time.sleep(0.2)  # Reduced delay for faster processing

    except KeyboardInterrupt:
        print("Exiting program...")
    except Exception as e:
        log_error(f"An unexpected error occurred: {e}")
    finally:
        if 'cap' in locals() and cap.isOpened():
            cap.release()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

