                self.b.seek(0)
                # Assuming some output sink 'out_h264' exists
                out_h264.write(self.b.read()) 
                self.b.seek(0)
                self.b.truncate(0)
            except IOError:
                log.error("Error writing frame data")
        else:
            try:
                self.b.write(d)
            except IOError:
                log.error("Error accumulating frame data")

class MotionDetectionBuffer:
    def __init__(self, f):
        self.f = f
        self.b = io.BytesIO()
        self.p = None
        self.c = None

    def write(self, d):
        if d.startswith(b'\xff\xd8'):
            try:
                self.b.seek(0)
                fd = self.b.read()
                if fd:
                    img = cv2.imdecode(np.frombuffer(fd, np.uint8), cv2.IMREAD_COLOR)
                    if img is not None:
                        if self.p is not None:
                            self.c = img.copy()
                            self.f(self.p.copy(), self.c.copy())
                        self.p = img
                    else:
                        log.warning("Failed to decode frame")
            except IOError:
                log.error("Error reading frame data")
            finally:
                self.b.seek(0)
                self.b.truncate(0)
        try:
            return self.b.write(d)
        except IOError:
            log.error("Error accumulating frame data")
            return 0

