# temperature_monitor.py
# A simple script to read and display CPU temperature on a Raspberry Pi 5.
# This version is designed for a classroom demonstration.

import time
import os
import smbus2

# I2C address of the OLED display (if used) - typically 0x3C
OLED_ADDRESS = 0x3C

# Initialize I2C bus
try:
    bus = smbus2.SMBus(1)  # Use 1 for Raspberry Pi 5
    print("I2C bus initialized successfully.")
except Exception as e:
    print(f"Error initializing I2C bus: {e}")
    bus = None  # Set bus to None if initialization fails

def get_cpu_temperature():
    """Reads the CPU temperature from the thermal zone file."""
    try:
        with open('/sys/class/thermal/thermal_zone0/temp', 'r') as f:
            temp_millidegrees = int(f.read().strip())
            temp_celsius = temp_millidegrees / 1000.0
            return temp_celsius
    except FileNotFoundError:
        print("Error: Thermal zone file not found.")
        return None
    except PermissionError:
        print("Error: Permission denied when reading thermal zone file.")
        return None
    except Exception as e:
        print(f"Error reading CPU temperature: {e}")
        return None

def main():
    """Main function to read and display CPU temperature."""
    try:
        while True:
            temperature = get_cpu_temperature()
            if temperature is not None:
                print(f"CPU Temperature: {temperature:.2f} °C")
            time.sleep(2)  # Wait 2 seconds
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        if bus:
            try:
                bus.close()
                print("I2C bus closed.")
            except Exception as e:
                print(f"Error closing I2C bus: {e}")

if __name__ == "__main__":
    main()

