import time
import board
import busio
import adafruit_character_lcd.character_lcd_i2c as character_lcd
import adafruit_dht
import signal
import sys

# Define LCD dimensions
LCD_COLUMNS = 16
LCD_ROWS = 2

# I2C address of the LCD backpack
LCD_ADDRESS = 0x27

# GPIO pin connected to the DHT22 sensor
DHT_PIN = board.D4

# Global variables for LCD and DHT22
lcd = None
dht_device = None

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_lcd(i2c_bus):
    """Initialize the LCD display."""
    try:
        return character_lcd.Character_LCD_I2C(i2c_bus, LCD_ADDRESS, LCD_COLUMNS, LCD_ROWS)
    except Exception as e:
        print(f"Error initializing LCD: {e}")
        return None

def initialize_dht22_sensor(pin):
    """Initialize the DHT22 sensor."""
    try:
        return adafruit_dht.DHT22(pin)
    except Exception as e:
        print(f"Error initializing DHT22 sensor: {e}")
        return None

def read_sensor_data(sensor):
    """Read temperature and humidity from the DHT22 sensor."""
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        return temperature, humidity
    except RuntimeError as e:
        print(f"DHT22 sensor error: {e}")
        return None, None
    except Exception as e:
        print(f"Unexpected error reading sensor: {e}")
        return None, None

def display_data(lcd_display, temperature, humidity):
    """Display temperature and humidity on the LCD."""
    try:
        if temperature is not None and humidity is not None:
            lcd_display.message = f"Temp: {temperature:.1f} C\nHumidity: {humidity:.1f}%"
        else:
            lcd_display.message = "Sensor Error"
    except Exception as e:
        print(f"Error displaying data: {e}")

def cleanup():
    """Clean up resources before exiting."""
    print("Cleaning up...")
    if lcd:
        try:
            lcd.clear()
        except Exception as e:
            print(f"Error clearing LCD: {e}")
    sys.exit(0)

def signal_handler(sig, frame):
    """Handle Ctrl+C gracefully."""
    print("Ctrl+C detected. Exiting...")
    cleanup()

def main():
    """Main function to read and display sensor data."""
    global lcd, dht_device

    # Initialize I2C
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        sys.exit(1)

    # Initialize LCD
    lcd = initialize_lcd(i2c_bus)
    if lcd is None:
        sys.exit(1)

    # Initialize DHT22 sensor
    dht_device = initialize_dht22_sensor(DHT_PIN)
    if dht_device is None:
        sys.exit(1)

    # Register signal handler for Ctrl+C
    signal.signal(signal.SIGINT, signal_handler)

    try:
        while True:
            # Read sensor data
            temperature, humidity = read_sensor_data(dht_device)

            # Display data on LCD
            display_data(lcd, temperature, humidity)

            # Wait before next reading
            time.sleep(2)

    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

