import smbus2
import time

# I2C address of the PCF8574 port expander
PCF8574_ADDRESS = 0x20
# Pin mask for all proximity sensors (P0-P7)
PROXIMITY_SENSORS_PIN = 0xFF
# Polling interval in seconds
POLL_INTERVAL = 0.1

def initialize_expander(bus):
    """Configure all pins as inputs with pull-up resistors enabled."""
    bus.write_byte(PCF8574_ADDRESS, PROXIMITY_SENSORS_PIN)

def read_sensor_states(bus):
    """Read the current state of all proximity sensors."""
    return bus.read_byte(PCF8574_ADDRESS)

def detect_obstacles(sensor_states):
    """Identify sensors detecting obstacles (LOW signal)."""
    return [index for index in range(8) if (sensor_states & (1 << index)) == 0]

def main():
    """Main function to continuously monitor proximity sensors."""
    try:
        with smbus2.SMBus(1) as i2c_bus:
            initialize_expander(i2c_bus)
            while True:
                try:
                    current_states = read_sensor_states(i2c_bus)
                    obstacle_sensors = detect_obstacles(current_states)
                    for sensor_index in obstacle_sensors:
                        print(f"Obstacle detected by sensor {sensor_index}")
                    time.sleep(POLL_INTERVAL)
                except Exception as read_error:
                    print(f"I2C read error: {read_error}")
                    time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as init_error:
        print(f"Initialization error: {init_error}")

if __name__ == "__main__":
    main()

