import time
import sys
from gpiozero import PWMOutputDevice, CPUTemperature

# Configuration: Adjust these values as needed
FAN_PIN = 18  # BCM pin connected to the fan
WAIT_TIME = 1  # Seconds between temperature checks
MIN_TEMP = 40  # Degrees Celsius - Fan at minimum speed
MAX_TEMP = 50  # Degrees Celsius - Fan at maximum speed

def get_cpu_temperature():
    """Reads the CPU temperature."""
    try:
        cpu = CPUTemperature()
        return cpu.temperature
    except Exception as e:
        print(f"Error reading CPU temperature: {e}")
        return None

def calculate_duty_cycle(temperature):
    """Calculates the fan speed (duty cycle) based on temperature."""
    if temperature is None:
        return 0  # Default to off if temperature reading fails

    clamped_temp = max(MIN_TEMP, min(temperature, MAX_TEMP))
    return (clamped_temp - MIN_TEMP) * 100 / (MAX_TEMP - MIN_TEMP)

def main():
    """Main function to control the fan."""
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=50)
        print("Fan control started. Press Ctrl+C to exit.")

        while True:
            temperature = get_cpu_temperature()
            duty_cycle = calculate_duty_cycle(temperature)
            fan.value = duty_cycle / 100

            if temperature is not None:
                print(f"Temperature: {temperature:.1f}°C, Fan Speed: {duty_cycle:.1f}%")

            time.sleep(WAIT_TIME)

    except KeyboardInterrupt:
        print("\nFan control stopped.")
    except Exception as e:
        print(f"\nAn error occurred: {e}")
    finally:
        # Ensure the fan is turned off when the program exits
        if 'fan' in locals():
            fan.value = 0
        sys.exit()

if __name__ == "__main__":
    main()

