import time
import requests
import adafruit_dht
import board

# Configuration
DHT_PIN = board.D4  # GPIO4 (physical pin 7)
SERVER_URL = 'http://127.0.0.1:5000/data'
READ_INTERVAL_SECONDS = 5

def initialize_dht_sensor(pin):
    """Initializes the DHT11 sensor."""
    return adafruit_dht.DHT11(pin)

def read_sensor_data(sensor):
    """Reads temperature and humidity from the DHT11 sensor."""
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        return temperature, humidity
    except RuntimeError as error:
        print(f"DHT11 Sensor Read Error: {error.args[0]}")
        return None, None
    except Exception as error:
        print(f"Unexpected DHT11 Error: {error}")
        return None, None

def send_data_to_server(url, temperature, humidity):
    """Sends temperature and humidity data to the server."""
    payload = {'temperature': temperature, 'humidity': humidity}
    try:
        response = requests.post(url, json=payload)
        response.raise_for_status()  # Raise HTTPError for bad responses (4xx or 5xx)
        print(f"Data sent successfully. Server response: {response.status_code}")
    except requests.exceptions.RequestException as e:
        print(f"Error sending data to server: {e}")

def main():
    """Main function to read sensor data and send it to the server."""
    dht_sensor = initialize_dht_sensor(DHT_PIN)

    try:
        while True:
            temperature, humidity = read_sensor_data(dht_sensor)

            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f} C, Humidity: {humidity:.1f} %")
                send_data_to_server(SERVER_URL, temperature, humidity)
            else:
                print("Failed to retrieve data from DHT11 sensor.")

            time.sleep(READ_INTERVAL_SECONDS)

    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        # No specific cleanup needed for adafruit_dht library, but good practice to include a finally block
        print("Exiting program.")

if __name__ == "__main__":
    main()

