import RPi.GPIO as GPIO
import time
import datetime
import csv
import fcntl
import logging
import random
import adafruit_dht

# Configuration
SENSOR_PINS = [17, 27]  # GPIO pins for DHT22 sensors
CSV_FILE_PREFIX = "retail_data"
ALERT_THRESHOLD_HIGH = 75
ALERT_THRESHOLD_LOW = 45
ALERT_DEBOUNCE_TIME = 30 * 60  # 30 minutes in seconds
MAX_RETRIES = 3
RETRY_DELAY = 2
CLOUD_SUCCESS_RATE = 0.8  # Simulated cloud push success rate

# Initialize logging
logging.basicConfig(filename='error.log', level=logging.ERROR,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# Global variables for alert tracking
high_humidity_alerts = {}
low_humidity_alerts = {}

def read_dht22(pin):
    """Reads temperature and humidity from a DHT22 sensor.

    Args:
        pin (int): The GPIO pin the sensor is connected to.

    Returns:
        tuple: (temperature, humidity) if successful, (None, None) otherwise.
    """
    dht_device = adafruit_dht.DHT22(pin, use_pulseio=False) # Initialize DHT22 sensor
    for attempt in range(MAX_RETRIES):
        try:
            temperature = dht_device.temperature
            humidity = dht_device.humidity
            if temperature is not None and humidity is not None:
                # Data validation
                if not (0 <= humidity <= 100 and 0 <= temperature <= 35):
                    logging.error(f"Invalid sensor reading from pin {pin}: Temperature={temperature}, Humidity={humidity}")
                    return None, None
                return temperature, humidity
            else:
                logging.warning(f"Failed to read from DHT22 sensor on pin {pin}, attempt {attempt + 1}")
                time.sleep(RETRY_DELAY)
        except Exception as e:
            logging.error(f"Error reading DHT22 sensor on pin {pin}: {e}")
            time.sleep(RETRY_DELAY)
    return None, None

def write_to_csv(data):
    """Writes sensor data to a CSV file.

    Args:
        data (list): A list of dictionaries, where each dictionary represents a row of data.
    """
    try:
        filename = f"{CSV_FILE_PREFIX}_{datetime.date.today().strftime('%Y-%m-%d')}.csv"
        file_exists = True
        try:
            with open(filename, 'r') as f:
                pass
        except FileNotFoundError:
            file_exists = False

        with open(filename, 'a', newline='') as csvfile:
            fieldnames = ['timestamp', 'sensor_id', 'temperature', 'humidity']
            writer = csv.DictWriter(csvfile, fieldnames=fieldnames)

            if not file_exists:
                writer.writeheader()

            fcntl.flock(csvfile.fileno(), fcntl.LOCK_EX)  # Acquire exclusive lock
            try:
                writer.writerows(data)
            finally:
                fcntl.flock(csvfile.fileno(), fcntl.LOCK_UN)  # Release lock
    except Exception as e:
        logging.error(f"Error writing to CSV file: {e}")

def check_alerts(sensor_id, humidity):
    """Checks for humidity alerts and logs them.

    Args:
        sensor_id (int): The ID of the sensor.
        humidity (float): The humidity reading.
    """
    global high_humidity_alerts, low_humidity_alerts
    now = time.time()

    if humidity > ALERT_THRESHOLD_HIGH:
        if sensor_id not in high_humidity_alerts:
            high_humidity_alerts[sensor_id] = []
        high_humidity_alerts[sensor_id].append(now)
        if len(high_humidity_alerts[sensor_id]) >= 3:
            if all(t > now - ALERT_DEBOUNCE_TIME for t in high_humidity_alerts[sensor_id]):
                logging.warning(f"High Humidity Alert: Sensor {sensor_id}, Humidity: {humidity}")
                log_alert(sensor_id, "High Humidity Alert", humidity)
                del high_humidity_alerts[sensor_id]  # Reset alert
    elif humidity < ALERT_THRESHOLD_LOW:
        if sensor_id not in low_humidity_alerts:
            low_humidity_alerts[sensor_id] = []
        low_humidity_alerts[sensor_id].append(now)
        if len(low_humidity_alerts[sensor_id]) >= 3:
            if all(t > now - ALERT_DEBOUNCE_TIME for t in low_humidity_alerts[sensor_id]):
                logging.warning(f"Low Humidity Alert: Sensor {sensor_id}, Humidity: {humidity}")
                log_alert(sensor_id, "Low Humidity Alert", humidity)
                del low_humidity_alerts[sensor_id]  # Reset alert
    else:
        # Reset alerts if humidity is back within range
        if sensor_id in high_humidity_alerts:
            del high_humidity_alerts[sensor_id]
        if sensor_id in low_humidity_alerts:
            del low_humidity_alerts[sensor_id]

def log_alert(sensor_id, alert_type, humidity):
    """Logs an alert to the retail_alerts.log file.

    Args:
        sensor_id (int): The ID of the sensor.
        alert_type (str): The type of alert.
        humidity (float): The humidity reading.
    """
    try:
        with open("retail_alerts.log", "a") as f:
            f.write(f"{datetime.datetime.now()} - Sensor {sensor_id} - {alert_type} - Humidity: {humidity}\n")
    except Exception as e:
        logging.error(f"Error writing to alert log: {e}")

def simulate_cloud_push(data):
    """Simulates pushing data to a cloud service.

    Args:
        data (list): A list of dictionaries representing the data to be pushed.
    """
    try:
        with open("cloud_log.log", "a") as f:
            f.write(f"{datetime.datetime.now()} - Attempting to push data to cloud...\n")
            if random.random() < CLOUD_SUCCESS_RATE:
                f.write(f"{datetime.datetime.now()} - Data successfully pushed to cloud.\n")
            else:
                f.write(f"{datetime.datetime.now()} - Failed to push data to cloud.\n")
    except Exception as e:
        logging.error(f"Error writing to cloud log: {e}")

def main():
    """Main function to read sensor data, log alerts, and push data to the cloud."""
    try:
        while True:
            data = []
            for i, pin in enumerate(SENSOR_PINS):
                temperature, humidity = read_dht22(pin)
                if temperature is not None and humidity is not None:
                    data.append({
                        'timestamp': datetime.datetime.now().isoformat(),
                        'sensor_id': i + 1,
                        'temperature': temperature,
                        'humidity': humidity
                    })
                    check_alerts(i + 1, humidity)
                else:
                    logging.warning(f"Failed to read data from sensor {i + 1}")

            if data:
                write_to_csv(data)
                simulate_cloud_push(data)  # Simulate pushing data to the cloud

            time.sleep(60)  # Read every 60 seconds

    except KeyboardInterrupt:
        print("Exiting program")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        GPIO.cleanup()  # Clean up GPIO on exit

if __name__ == "__main__":
    main()

