from MCP23017_I2C import *

# Import the time library for pausing
import time

# Define the I2C address of the MCP23017 chip
MCP23017_ADDRESS = 0x20

# Define the GPIO pin connected to the LED (GPA0)
LED_PIN = 0

# Define the GPIO pin connected to the switch (GPB7)
SWITCH_PIN = 7

# Define the I2C bus number (0 for older Pis, 1 for newer ones)
I2C_BUS = 0

# Initialize the MCP23017 chip
try:
    mcp = GPIO_CHIP(MCP23017_ADDRESS, I2C_BUS)
except Exception as e:
    print(f"Error initializing MCP23017: {e}")
    exit()

# Set up the LED pin as output
try:
    mcp.setup(LED_PIN, 'OUT', 'A')
except Exception as e:
    print(f"Error setting up LED pin: {e}")
    exit()

# Set up the switch pin as input with pull-up resistor
try:
    mcp.setup(SWITCH_PIN, 'IN', 'B', pullup=True)
except Exception as e:
    print(f"Error setting up switch pin: {e}")
    exit()

# Main loop
try:
    while True:
        # Read the switch state
        try:
            switch_state = mcp.input(SWITCH_PIN, 'B')
        except Exception as e:
            print(f"Error reading switch state: {e}")
            switch_state = 1 # Assume switch is open to avoid issues

        # Turn the LED on if the switch is pressed (switch_state is 0)
        if switch_state == 0:
            try:
                mcp.output(LED_PIN, 1, 'A')
                print("Led ON")
            except Exception as e:
                print(f"Error turning LED on: {e}")
        # Turn the LED off if the switch is not pressed (switch_state is 1)
        else:
            try:
                mcp.output(LED_PIN, 0, 'A')
                print("Led OFF")
            except Exception as e:
                print(f"Error turning LED off: {e}")

        # Wait a short time
        time.sleep(0.1)

# Handle Ctrl+C (exit the program gracefully)
except KeyboardInterrupt:
    print("Exiting...")
    # Turn off the LED before exiting
    try:
        mcp.output(LED_PIN, 0, 'A')
    except Exception as e:
        print(f"Error turning LED off during exit: {e}")

