import sys
import threading
import time
import RPi.GPIO as GPIO
import DOGProtocol as DOG  # Assuming this module exists

# Constants
DEFAULT_LOG_FILE = "data.log"
PROTOCOL_END_CHAR = '$'

# Configuration
GPIO.setwarnings(False)
GPIO.setmode(GPIO.BCM)

# Global State (using a dictionary for better organization)
server_state = {
    'is_running': False,
    'log_file_path': DEFAULT_LOG_FILE,
    'receive_thread': None,
    'log_file': None,
}


# Utility Functions
def log_message(message):
    """Appends a message to the log file with timestamp."""
    try:
        if server_state['log_file']:
            timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
            server_state['log_file'].write(f"{timestamp}: {message}\n")
            server_state['log_file'].flush()  # Ensure immediate write
    except Exception as e:
        print(f"Error writing to log: {e}")


def display_help(command=None):
    """Displays help information for a specific command or general help."""
    help_texts = {
        'help': "Help: 'help [command]' displays help for the specified command. Omitting the command shows general help.",
        'start': "Start: 'start <filename>' starts logging to the specified file.",
        'stop': "Stop: 'stop' stops the server.",
        'display': "Display: 'display' displays the contents of the log file.",
        'send': "Send: 'send <data>' sends data using the DOGProtocol.",
        'write': "Write: 'write <data>' directly writes data to the log file.",
        'exit': "Exit: 'exit' stops the server and exits."
    }

    if command:
        print(help_texts.get(command, "No help found for this command."))
    else:
        print("\nAvailable commands:")
        for cmd in help_texts:
            print(f"  {cmd}")
        print("Use 'help <command>' for more information.\n")


# Server Functions
def initialize_server(log_file_path):
    """Initializes server state and opens the log file."""
    global server_state
    try:
        server_state['log_file'] = open(log_file_path, 'a+')  # Open in append mode
        server_state['log_file_path'] = log_file_path
        return True
    except Exception as e:
        print(f"Error initializing server: {e}")
        return False


def finalize_server():
    """Stops the server and closes resources."""
    global server_state
    if server_state['receive_thread']:
        stop_receive_thread()
    if server_state['log_file']:
        try:
            server_state['log_file'].close()
        except Exception as e:
            print(f"Error closing log file: {e}")
    server_state = {  # Reset server state
        'is_running': False,
        'log_file_path': DEFAULT_LOG_FILE,
        'receive_thread': None,
        'log_file': None,
    }
    GPIO.cleanup()
    print("Server stopped.")


def receive_data():
    """Continuously receives data and logs it to the file."""
    try:
        while server_state['is_running']:
            data = DOG.receive()  # Blocking receive
            if data:
                log_message(data)
            time.sleep(0.1) # Add a small delay to reduce CPU usage
    except Exception as e:
        print(f"Receive thread error: {e}")
    finally:
        print("Receive thread stopped.")


def start_receive_thread():
    """Starts the data receive thread."""
    if not server_state['is_running']:
        print("Server must be started first.")
        return

    if server_state['receive_thread'] is None or not server_state['receive_thread'].is_alive():
        server_state['receive_thread'] = threading.Thread(target=receive_data, daemon=True)
        server_state['receive_thread'].start()
        print("Receive thread started.")
    else:
        print("Receive thread is already running.")


def stop_receive_thread():
    """Stops the data receive thread."""
    if server_state['receive_thread'] and server_state['receive_thread'].is_alive():
        server_state['is_running'] = False  # Set flag to stop the thread
        server_state['receive_thread'].join()  # Wait for thread to finish
        server_state['receive_thread'] = None
        print("Receive thread stopped.")
    else:
        print("Receive thread is not running.")


# Command Handlers
def handle_start(args):
    """Starts the server with the given log file."""
    global server_state
    if server_state['is_running']:
        print("Server is already running.")
        return

    if len(args) != 2:
        print("Usage: start <filename>")
        return

    log_file_path = args[1]
    if initialize_server(log_file_path):
        server_state['is_running'] = True
        start_receive_thread()
        print(f"Server started. Logging to {log_file_path}")
    else:
        print("Failed to start server.")


def handle_stop(args):
    """Stops the server."""
    global server_state
    if not server_state['is_running']:
        print("Server is not running.")
        return
    finalize_server()


def handle_display(args):
    """Displays the contents of the log file."""
    global server_state
    if not server_state['is_running']:
        print("Server is not running.")
        return

    try:
        if server_state['log_file']:
            server_state['log_file'].seek(0)  # Go to the beginning of the file
            print(server_state['log_file'].read())
        else:
            print("Log file not available.")
    except Exception as e:
        print(f"Error displaying log: {e}")


def handle_send(args):
    """Sends data using the DOGProtocol."""
    global server_state
    if not server_state['is_running']:
        print("Server is not running.")
        return

    if len(args) < 2:
        print("Usage: send <data>")
        return

    data = " ".join(args[1:])
    try:
        DOG.send(data)
        log_message(f"Sent: {data}") # Log the sent data as well
        print(f"Sent: {data}")
    except Exception as e:
        print(f"Error sending data: {e}")


def handle_write(args):
    """Writes data directly to the log file."""
    global server_state
    if not server_state['is_running']:
        print("Server is not running.")
        return

    if len(args) < 2:
        print("Usage: write <data>")
        return

    data = " ".join(args[1:])
    log_message(data)
    print(f"Wrote to log: {data}")


def handle_exit(args):
    """Exits the server and cleans up GPIO."""
    print("Exiting server...")
    finalize_server()
    sys.exit(0)


# Command Dispatch
command_handlers = {
    'start': handle_start,
    'stop': handle_stop,
    'display': handle_display,
    'send': handle_send,
    'write': handle_write,
    'exit': handle_exit,
    'help': display_help
}


def execute_command(command_line):
    """Parses the command line and executes the corresponding handler."""
    args = command_line.split()
    if not args:
        return

    command = args[0].lower()
    handler = command_handlers.get(command)

    if handler:
        handler(args)
    else:
        print(f"Unknown command: {command}. Try 'help'.")


# Signal Handler for Clean Exit
def signal_handler(sig, frame):
    print("\nReceived signal, exiting gracefully...")
    finalize_server()
    sys.exit(0)


# Main Server Loop
def main():
    """Main server loop that reads commands from stdin."""
    import signal
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    print("DOGServer started. Type 'help' for commands.")
    try:
        while True:
            try:
                command = input("DOGServer> ")
                execute_command(command)
            except KeyboardInterrupt:
                print("\nKeyboard interrupt, exiting gracefully...")
                break
            except Exception as e:
                print(f"Error processing command: {e}")
    finally:
        finalize_server()


if __name__ == "__main__":
    main()

