import RPi.GPIO as GPIO
import time
import logging
import signal
import sys

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Define GPIO pins using BCM numbering
DATA_OUT_PIN = 5
TIMER_OUT_PIN = 6
DATA_IN_PIN = 20
TIMER_IN_PIN = 21

# Protocol Constants
START_SIGNAL = [1, 0, 1, 1, 1, 1, 1, 1]
END_SIGNAL = [1, 1, 1, 1, 1, 1, 1, 1]
BASE_BUFFER = [0, 0, 0, 0, 0, 0, 0, 0]

# Timing constants (seconds)
TRANSMIT_DELAY = 0.0005
RECEPTION_TIMEOUT = 1  # Timeout in seconds for reception

# Global flag for graceful shutdown
shutdown_flag = False

def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    global shutdown_flag
    logging.info("Received signal, shutting down...")
    shutdown_flag = True

# Register signal handlers
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)


class GPIOError(Exception):
    """Custom exception for GPIO related errors."""
    pass


def initialize_gpio():
    """Initializes GPIO pins. Use BCM numbering."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)  # Suppress warnings
        logging.info("GPIO mode set to BCM.")
    except Exception as e:
        raise GPIOError(f"Error initializing GPIO: {e}")


def cleanup_gpio():
    """Cleans up GPIO resources."""
    try:
        GPIO.cleanup()
        logging.info("GPIO cleanup completed.")
    except Exception as e:
        logging.error(f"Error during GPIO cleanup: {e}")


def char_to_buffer(char: str) -> list[int]:
    """Converts a character to a buffer (list of bits)."""
    if not isinstance(char, str) or len(char) != 1:
        raise ValueError("Input must be a single character.")
    ascii_value = ord(char)
    return [0] + [int(bit) for bit in bin(ascii_value)[2:].zfill(7)]


def buffer_to_char(buffer: list[int]) -> str:
    """Converts a buffer (list of bits) to a character."""
    if not isinstance(buffer, list) or len(buffer) != 8 or not all(isinstance(bit, int) for bit in buffer):
        raise ValueError("Invalid buffer format.")
    return chr(int("".join(map(str, buffer[1:])), 2))


def string_to_buffer_list(input_string: str) -> list[list[int]]:
    """Converts a string to a list of buffers."""
    if not isinstance(input_string, str):
        raise TypeError("Input must be a string.")
    return [char_to_buffer(char) for char in input_string]


def buffer_list_to_string(buffer_list: list[list[int]]) -> str:
    """Converts a list of buffers to a string, ignoring start and end signals."""
    if not isinstance(buffer_list, list):
        raise TypeError("Input must be a list.")
    return "".join(buffer_to_char(buffer) for buffer in buffer_list if buffer not in (START_SIGNAL, END_SIGNAL))


def transmit_bit(bit: int, data_pin: int, timer_pin: int):
    """Transmits a single bit."""
    if bit not in (0, 1):
        raise ValueError("Bit must be 0 or 1.")
    GPIO.output(timer_pin, GPIO.LOW)
    GPIO.output(data_pin, bit)
    time.sleep(TRANSMIT_DELAY)
    GPIO.output(timer_pin, GPIO.HIGH)
    time.sleep(TRANSMIT_DELAY)
    GPIO.output(timer_pin, GPIO.LOW)


def transmit_buffer(buffer: list[int], data_pin: int, timer_pin: int):
    """Transmits a buffer (list of bits)."""
    if not isinstance(buffer, list):
        raise TypeError("Buffer must be a list.")
    for bit in buffer:
        transmit_bit(bit, data_pin, timer_pin)


def send_data(data_string: str, data_pin: int, timer_pin: int):
    """Sends a string over the data protocol."""
    if not isinstance(data_string, str):
        raise TypeError("Data must be a string.")

    try:
        initialize_gpio()
        GPIO.setup(data_pin, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(timer_pin, GPIO.OUT, initial=GPIO.LOW)

        buffer_list = string_to_buffer_list(data_string) + [END_SIGNAL]

        for buffer in buffer_list:
            transmit_buffer(buffer, data_pin, timer_pin)

        logging.info(f"Data sent successfully: {data_string}")

    except Exception as e:
        logging.error(f"Error sending data: {e}")
        raise
    finally:
        cleanup_gpio()



def receive_bit(data_pin: int, timer_pin: int, timeout: float) -> int:
    """Receives a single bit with timeout."""
    start_time = time.time()
    while GPIO.input(timer_pin) == GPIO.LOW:
        if time.time() - start_time > timeout:
            raise TimeoutError("Timeout receiving bit.")
    return GPIO.input(data_pin)


def receive_buffer(data_pin: int, timer_pin: int, timeout: float) -> list[int]:
    """Receives a buffer (8 bits) with timeout."""
    buffer = []
