from typing import Callable, Dict, List, Any
from worker_DAC8532 import DAC8532
from worker_K10CR1 import K10CR1

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

class SubscriptionHandler:
    """Handles subscriptions and unsubscriptions for data streams."""

    def __init__(self, sub_sock: zmq.Socket, sub_list: Dict[str, str]):
        """
        Initializes the SubscriptionHandler.

        Args:
            sub_sock: The ZMQ subscriber socket.
            sub_list: A dictionary mapping stream filters to channel IDs.
        """
        self.sub_sock = sub_sock
        self.sub_list = sub_list
        self.subscriptions: Dict[str, List[str]] = {}  # {stream_filter: [channel_ids]}
        self.channel_info: Dict[str, Dict[str, Any]] = {}  # {channel_id: {kwargs, control}}

    def handle_subscription(self, stream_filter: str, channel_id: str, kwargs: Dict[str, Any]) -> None:
        """Handles a subscription request."""
        if stream_filter not in self.subscriptions:
            self.subscriptions[stream_filter] = []
            try:
                self.sub_sock.setsockopt_string(zmq.SUBSCRIBE, stream_filter)
            except zmq.ZMQError as e:
                logger.error(f"ZMQ error setting subscribe option: {e}")
                raise

        if channel_id not in self.subscriptions[stream_filter]:
            self.subscriptions[stream_filter].append(channel_id)
            self.channel_info[channel_id] = {'kwargs': kwargs, 'control': {'alert': True, 'pause': False}}

    def handle_unsubscription(self, stream_filter: str, channel_id: str) -> None:
        """Handles an unsubscription request."""
        if stream_filter in self.subscriptions and channel_id in self.subscriptions[stream_filter]:
            self.subscriptions[stream_filter].remove(channel_id)
            try:
                self.sub_sock.setsockopt_string(zmq.UNSUBSCRIBE, stream_filter)
            except zmq.ZMQError as e:
                logger.error(f"ZMQ error setting unsubscribe option: {e}")
                raise

            if not self.subscriptions[stream_filter]:
                del self.subscriptions[stream_filter]

    def get_subscriptions(self) -> Dict[str, List[str]]:
        """Returns the current subscriptions."""
        return self.subscriptions



class PIDHandler:
    """Handles PID controller updates and error signal output."""

    def __init__(self, config: Dict[str, Any], global_kwargs: Dict[str, Any]):
        """Initializes the PIDHandler."""
        self.pids: Dict[str, Any] = {}
        self.global_kwargs = global_kwargs
        self.k10cr1 = K10CR1(config.get('pid_params', {}).get('K10CR1', {}), **global_kwargs)
        self.dac8532 = DAC8532(config.get('pid_params', {}).get('DAC8532', {}), **global_kwargs)
        self.error_signals: Dict[str, bool] = {}  # {channel_id: error_state}
        self.last_error_time: Dict[str, float] = {}  # {channel_id: timestamp}
        self.last_msg: Dict[str, float] = {}  # {channel_id: timestamp}
        self.pwm_mode = config.get('pwm_mode', False)
        self.gpio_pin = config.get('gpio_pin', 10)
        self.failure_mode = config.get('failure_mode', 'reset')
        self.dac_a = config.get('dac_a', None)
        self.dac_b = config.get('dac_b', None)
        self.feedback_device = config.get('feedback_device', None)
        self.feedback_params = config.get('feedback_params', [])

        GPIO.setmode(GPIO.BOARD)
        GPIO.setup(self.gpio_pin, GPIO.OUT)
        self.pwm = GPIO.PWM(self.gpio_pin, 1000)  # 1 kHz PWM frequency
        self.pwm.start(0)  # Start with 0% duty cycle

        self.k10cr1.run()
        self.dac8532.run()

    def update_pid(self, channel_id: str, pid_data: Dict[str, Any]) -> None:
        """Updates the PID controller for a given channel."""
        try:
            self.pids[channel_id] = self.k10cr1.add_pid(channel_id, pid_data)
            self.pids[channel_id].set_kwargs(self.global_kwargs)
            self.error_signals[channel_id] = False
            self.last_error_time[channel_id] = time.time()
        except Exception as e:
            logger.error(f"Error updating PID for channel {channel_id}: {e}")


    def update_error_output(self) -> None:
        """Updates the error signal output based on PID errors."""
        current_time = time.time()
        any_error = False
        for channel_id, error_state in self.error_signals.items():
            if error_state:
                any_error = True
                if channel_id in self.last_error_time and (current_time - self.last_error_time[channel_id] > 20):
                    self.set_error_output(channel_id, False)

        if not any_error:
            self.set_error_output('all', False)
        elif self.pwm_mode:
            self.pwm.ChangeDutyCycle(100)
        else:
            GPIO.output(self.gpio_pin, GPIO.HIGH)


    def set_error_output(self, channel_id: str, error_state: bool) -> None:
        """Sets the error output for a specific channel or all channels."""
        if channel_id == 'all':
            if self.pwm_mode:
                self.pwm.ChangeDutyCycle(0)
            else:
                GPIO.output(self.gpio_pin, GPIO.LOW)
        elif channel_id in self.error_signals:
            self.error_signals[channel_id] = error_state
            if error_state:
                if self.pwm_mode:
                    self.pwm.ChangeDutyCycle(100)
                else:
                    GPIO.output(self.gpio_pin, GPIO.HIGH)
            else:
                self.update_error_output()  # Recalculate if any other channel is not error

            if error_state and self.feedback_device:
                try:
                    self.feedback_device.set_channel(kwargs=self.feedback_params, value=0) # Assuming 0 means error state
                except Exception as e:
                    logger.error(f"Error setting feedback for channel {channel_id}: {e}")

            if self.dac_a:
                dac_value = self.dac8532.values[0] if self.dac8532.values else 0  # Use 0 as default
                self.dac_a.set_value(dac_value)
            if self.dac_b:
                dac_value = self.dac8532.values[1] if self.dac8532.values else 0  # Use 0 as default
                self.dac_b.set_value(dac_value)


    def reset_error(self, channel_id: str) -> None:
        """Resets the error state for a given channel."""
        if channel_id in self.last_error_time:
            del self.last_error_time[channel_id]
        self.set_error_output(channel_id, False)

    def cleanup(self) -> None:
        """Cleans up GPIO resources."""
        self.pwm.stop()
        GPIO.cleanup()

    def get_pid_status(self) -> Dict[str, Any]:
        """Returns the current PID status."""
        return {
            'error_signals': self.error_signals,
            'last_error_time': self.last_error_time,
        }


class GenericHandler:
    """Handles generic commands via HTTP requests."""

    def __init__(self, config: Dict[str, Any], global_kwargs: Dict[str, Any]):
        """Initializes the GenericHandler."""
        self.config = config
        self.global_kwargs = global_kwargs
        self.logger = logger

    def handle_command(self, command: str, channel_id: str, action: str, value: Any = None) -> None:
        """Handles a generic command via HTTP request."""
        url = f"{self.config['control']}/{command}/{channel_id}"
        params = {'action': action}
        if value is not None:
            params['value'] = value

        try:
            response = requests.get(url, params=params, timeout=5)
            response.raise_for_status()
            self.logger.info(f"Command '{command}' sent successfully. Status code: {response.status_code}")
        except requests.exceptions.RequestException as e:
            self.logger.error(f"Error sending command '{command}': {e}")


class DataHandler:
    """Handles incoming data, updates PID controllers, and manages subscriptions."""

    def __init__(self, config: Dict[str, Any], sub_sock: zmq.Socket, global_kwargs: Dict[str, Any]):
        """Initializes the DataHandler."""
        self.config = config
        self.sub_sock = sub_sock
        self.global_kwargs = global_kwargs
        self.pid_handler = PIDHandler(config, global_kwargs)
        self.subscription_handler = SubscriptionHandler(sub_sock, config.get('sub_list', {}))
        self.last_msg: Dict[str, float] = {}
        self.last_seq: Dict[str, int] = {}
        self.bookmarks: Dict[str, int] = {}
        self.subscriptions: Dict[str, List[str]] = {}
        self.generic_handler = GenericHandler(config, global_kwargs)
        self.global_err_state = False
        self.global_last_msg = 0

    def handle_message(self, msg: Dict[str, Any]) -> None:
        """Handles an incoming message."""
        self.global_last_msg = time.time()
        stream_filter = msg.get('stream_filter')
        channel_id = msg.get('id')
        data = msg.get('data')
        header = msg.get('header', {})
        status = header.get('status')

        if not stream_filter or not channel_id:
            self.logger.error("Invalid message format: 'stream_filter' and 'id' are required.")
            return

        if status == 10:
            self.handle_subscription(stream_filter, channel_id, header.get('kwargs', {}))
        elif status == 20:
            self.handle_unsubscription(stream_filter, channel_id)
        elif status == 90:
            self.handle_update_interval(header)
        elif status == 91:
            self.handle_subscription(header.get('stream_filter'), header.get('id'), header.get('kwargs', {}))
        elif status == 92:
            self.handle_unsubscription(header.get('stream_filter'), header.get('id'))
        elif status == 99:
            self.handle_bookmark(header)
        elif status == 100:
            self.handle_reset(channel_id)
        elif status == 110:
            self.handle_pause(header.get('id'))
        elif status == 111:
            self.handle_resume(header.get('id'))
        elif status == 120:
            self.handle_mute(header.get('id'))
        elif status == 121:
            self.handle_unmute(header.get('id'))
        elif status == 130:
            self.handle_trigger(header.get('id'))
        elif status == 140:
            self.handle_seek(header.get('id'))
        elif status == 150:
            self.handle_feedback(header.get('id'))
        elif status == 160:
            self.handle_feedback_end(header.get('id'))
        elif status == 200:
            self.handle_metadata(data, header)
        elif status >= 210 and status < 230:
            self.handle_data(data, header)
        elif status == 230:
            self.handle_error(data, header)
        elif status == 240:
            self.handle_end_stream(data, header)
        elif status == 250:
            self.handle_close_stream(data, header)
        else:
            self.logger.warning(f"Unknown status code: {status}")

        self.last_msg[channel_id] = time.time()
        self.update_subscriptions()
        self.pid_handler.last_msg[channel_id] = self.last_msg.get(channel_id, 0)
        self.check_error_state()

    def handle_subscription(self, stream_filter: str, channel_id: str, kwargs: Dict[str, Any]) -> None:
        """Handles a subscription request."""
        self.subscription_handler.handle_subscription(stream_filter, channel_id, kwargs)
        self.subscriptions = self.subscription_handler.get_subscriptions()

    def handle_unsubscription(self, stream_filter: str, channel_id: str) -> None:
        """Handles an unsubscription request."""
        self.subscription_handler.handle_unsubscription(stream_filter, channel_id)
        self.subscriptions = self.subscription_handler.get_subscriptions()

    # ... (rest of the handle_* methods)

    def update_subscriptions(self) -> None:
        """Updates the subscriptions based on the last message received."""
        current_time = time.time()
        for channel_id, last_msg_time in self.last_msg.items():
            if (current_time - last_msg_time) > 20:
                self.pid_handler.set_error_output(channel_id, True)
                self.pid_handler.last_error_time[channel_id] = current_time

        for channel_id, last_msg_time in self.last_msg.items():
            if (current_time - last_msg_time) > 20:
                try:
                    self.sub_sock.setsockopt_string(zmq.UNSUBSCRIBE, self.subscription_handler.sub_list.get(channel_id))
                except zmq.ZMQError as e:
                    logger.error(f"ZMQ error unsubscribing: {e}")

    def check_error_state(self) -> None:
        """Checks and updates the global error state."""
        self.global_err_state = any(self.pid_handler.error_signals.values())
        if self.global_err_state:
            self.pid_handler.set_error_output('all', True)
        else:
            self.pid_handler.update_error_output()

    def run(self) -> None:
        """Runs the main data handling loop."""
        try:
            while True:
                try:
                    [msg] = self.sub_sock.recv_multipart(flags=zmq.NOBLOCK)
                    try:
                        msg = json.loads(msg.decode('utf-8'))
                        self.handle_message(msg)
                    except json.JSONDecodeError as e:
                        logger.error(f"Invalid JSON received: {e}")
                except zmq.ZMQError as e:
                    if e.errno == zmq.EAGAIN:
                        time.sleep(0.05)
                        current_time = time.time()
                        if (current_time - self.global_last_msg) > 10:
                            self.check_error_state()
                        continue
                    else:
                        raise
        except KeyboardInterrupt:
            logger.info("DataHandler interrupted.")
        finally:
            self.pid_handler.cleanup()

