    try:
        fingerprint_sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus)
        return True
    except RuntimeError as e:
        print(f"Error initializing fingerprint sensor: {e}")
        return False
    except Exception as e:
        print(f"Unexpected error initializing fingerprint sensor: {e}")
        return False

def authenticate_fingerprint():
    """Authenticates a fingerprint against the stored templates."""
    try:
        print("Waiting for finger...")
        while fingerprint_sensor.get_image() != adafruit_fingerprint.OK:
            pass

        print("Templating...")
        if fingerprint_sensor.image_2_tz(1) != adafruit_fingerprint.OK:
            print("Templating failed.")
            return False

        print("Searching...")
        if fingerprint_sensor.finger_search() != adafruit_fingerprint.OK:
            print("Fingerprint not found.")
            return False

        print("Access Granted")
        return True

    except Exception as e:
        print(f"An error occurred during authentication: {e}")
        return False

def main():
    """Main function to run the fingerprint authentication loop."""
    if not initialize_i2c():
        print("Failed to initialize I2C. Exiting.")
        return

    if not initialize_fingerprint_sensor():
        print("Failed to initialize fingerprint sensor. Exiting.")
        return

    try:
        while True:
            if authenticate_fingerprint():
                # Placeholder for actions to take upon successful authentication
                pass
            else:
                print("Access Denied")
            time.sleep(1)  # Short delay between attempts

    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        # Cleanup resources
        if i2c_bus:
            i2c_bus.deinit()
        print("I2C bus deinitialized.")

if __name__ == "__main__":
    main()

