import RPi.GPIO as GPIO
import time
import sys
import getopt
import os

# Constants
DEFAULT_DEBOUNCE_MS = 200
LOG_LENGTH = 5

# Global variables
gpio_ch = []
gpio_state = []
gpio_log = []
debounce_time = DEFAULT_DEBOUNCE_MS
model = "Unknown"

# --- Functional approach ---

def get_raspi_model():
    """Detects the Raspberry Pi model."""
    try:
        with open('/proc/cpuinfo', 'r') as f:
            for line in f:
                if line.startswith('Revision'):
                    revision = int(line.split(':')[1], 16)
                    if revision < 3:
                        return "Rev 1"  # Early 256MB Pis
                    else:
                        return "Rev 2"  # Later 512MB Pis (including 3B+)
    except Exception as e:
        print(f"Error detecting model: {e}")
        return "Unknown"

def get_gpio_num(model):
    """Returns the number of GPIO pins based on the model."""
    if model == "Rev 1":
        return 17
    else:
        return 26 # Or 40 in newer Pis, but we treat them the same for simplicity

def setup_gpio(gpio_num):
    """Sets up the GPIO pins."""
    global gpio_ch, gpio_state
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    gpio_ch = []
    gpio_state = []
    for i in range(gpio_num):
        pin = i
        GPIO.setup(pin, GPIO.IN)
        gpio_ch.append(pin)
        gpio_state.append(0)

def gpio_callback(channel):
    """Callback function for GPIO events."""
    global gpio_state, gpio_log
    try:
        pin_index = gpio_ch.index(channel)
        new_state = GPIO.input(channel)
        if new_state != gpio_state[pin_index]:
            gpio_state[pin_index] = new_state
            timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
            log_entry = f"{timestamp}: GPIO {channel} -> {new_state}"
            gpio_log.append(log_entry)
            if len(gpio_log) > LOG_LENGTH:
                gpio_log.pop(0)
            print(log_entry) # Print to console
    except Exception as e:
        print(f"Error in callback: {e}")

def monitor_gpio(debounce_time):
    """Monitors GPIO pins for events."""
    try:
        for pin in gpio_ch:
            GPIO.add_event_detect(pin, GPIO.BOTH, callback=gpio_callback, bouncetime=debounce_time)
        print('Monitoring...')
        while True:
            time.sleep(1)  # Keep the script running
    except KeyboardInterrupt:
        print("Exiting...")
    finally:
        GPIO.cleanup()
        print("GPIO cleanup done.")

def print_help():
    """Prints help information."""
    print("Usage: sudo python script.py [-d <debounce_time_ms>]")
    print("  -d, --debounce <ms>  Set debounce time in milliseconds (default: 200)")

def main(argv):
    """Main function."""
    global debounce_time, model

    try:
        opts, args = getopt.getopt(argv, "hd:", ["help", "debounce="])
    except getopt.GetoptError:
        print_help()
        sys.exit(2)

    for opt, arg in opts:
        if opt in ("-h", "--help"):
            print_help()
            sys.exit()
        elif opt in ("-d", "--debounce"):
            try:
                debounce_time = int(arg)
            except ValueError:
                print("Debounce time must be an integer.")
                sys.exit(2)

    model = get_raspi_model()
    gpio_num = get_gpio_num(model)
    print(f"Detected model: {model}, GPIO pins: {gpio_num}")

    try:
        setup_gpio(gpio_num)
        monitor_gpio(debounce_time)
    except RuntimeError as e:
        print(f"Error: Could not initialize GPIO. Are you running as root? Error: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main(sys.argv[1:])

