# Light-sensitive LED brightness controller for Raspberry Pi
# Reads ambient light from a TSL2561 over I2C and adjusts an LED brightness
import time
import board
import busio
import adafruit_tsl2561
from gpiozero import PWMLED

# I2C address of the light sensor
TSL2561_I2C_ADDRESS = 0x39
# GPIO pin for the LED
LED_GPIO_PIN = 18
# PWM frequency in Hz
PWM_FREQUENCY = 1000

def clamp(value, min_value, max_value):
    """Clamps a value within a given range."""
    return max(min_value, min(value, max_value))

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_light_sensor(i2c_bus):
    """Initializes the TSL2561 light sensor."""
    try:
        return adafruit_tsl2561.TSL2561(i2c_bus, address=TSL2561_I2C_ADDRESS)
    except Exception as e:
        print(f"Error initializing light sensor: {e}")
        return None

def initialize_led(gpio_pin, frequency):
    """Initializes the PWM LED."""
    try:
        return PWMLED(gpio_pin, frequency=frequency)
    except Exception as e:
        print(f"Error initializing LED: {e}")
        return None

def read_light_level(sensor):
    """Reads the light level from the sensor."""
    try:
        return sensor.lux
    except Exception as e:
