#!/usr/bin/python3

"""
Provides a robust and optimized driver for PWM duty cycle control of a DC motor
using an L298N motor driver and a Raspberry Pi.
"""

import pigpio
import logging

# Configure logging (optional, but recommended)
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class MotorError(Exception):
    """Custom exception for motor-related errors."""
    pass

class Motor:
    """
    Controls a DC motor using an L298N motor driver via pigpio.

    Attributes:
        pi (pigpio.pi): pigpio instance.
        pin (int): GPIO pin connected to the motor driver's input.
        frequency (int): PWM frequency in Hz.
        inverted (bool): Whether the motor direction is inverted.
        _duty_cycle (int): Current duty cycle (-255 to 255).
    """

    def __init__(self, pi: pigpio.pi, pin: int, frequency: int = 1000, inverted: bool = False):
        """Initializes the motor."""

        if not isinstance(pi, pigpio.pi):
            raise MotorError("Invalid pigpio instance provided.")
        if not isinstance(pin, int):
            raise MotorError("Invalid GPIO pin provided.")

        self.pi = pi
        self.pin = pin
        self.frequency = frequency
        self.inverted = inverted
        self._duty_cycle = 0

        try:
            self.pi.set_mode(self.pin, pigpio.OUTPUT)
            self.pi.set_PWM_frequency(self.pin, self.frequency)
            self.set_duty_cycle(0)  # Ensure motor starts stopped
        except pigpio.error as e:
            raise MotorError(f"Error initializing motor: {e}")


    def set_frequency(self, frequency: int) -> None:
        """Sets the PWM frequency."""
        if not isinstance(frequency, int) or not 0 < frequency < 20000:  # Reasonable frequency range
            raise MotorError("Invalid frequency value.")
        try:
            self.pi.set_PWM_frequency(self.pin, frequency)
            self.frequency = frequency
        except pigpio.error as e:
            raise MotorError(f"Error setting frequency: {e}")


    def set_duty_cycle(self, duty_cycle: int) -> None:
        """Sets the motor's duty cycle."""
        if not isinstance(duty_cycle, int) or not -255 <= duty_cycle <= 255:
            raise MotorError("Invalid duty cycle value.")

        if duty_cycle == self._duty_cycle:
            return

        duty_cycle = duty_cycle if not self.inverted else -duty_cycle
        try:
            self.pi.set_PWM_dutycycle(self.pin, abs(duty_cycle))
            self._duty_cycle = duty_cycle
            if duty_cycle > 0:
                self.pi.set_PWM_frequency(self.pin, self.frequency) # Start PWM if stopped
            elif duty_cycle == 0:
                self.pi.set_PWM_dutycycle(self.pin, 0) # Stop PWM
        except pigpio.error as e:
            raise MotorError(f"Error setting duty cycle: {e}")


    def stop(self) -> None:
        """Stops the motor."""
        self.set_duty_cycle(0)

    def close(self):
        """Releases resources."""
        try:
            self.pi.set_PWM_dutycycle(self.pin, 0)  # Ensure motor is stopped
            self.pi.set_mode(self.pin, pigpio.INPUT) # Release the GPIO pin
        except pigpio.error as e:
            logging.error(f"Error during cleanup: {e}")  # Log the error, but don't re-raise

    def get_status(self) -> dict:
        """Returns the motor's current status."""
        return {
            "pin": self.pin,
            "frequency": self.frequency,
            "inverted": self.inverted,
            "duty_cycle": self._duty_cycle,
        }

