import time
import board
import busio
import adafruit_seesaw.seesaw
import RPi.GPIO as GPIO

# Define constants
I2C_ADDRESS = 0x36
PUMP_GPIO_PIN = 17
DRY_SOIL_THRESHOLD = 500
READ_INTERVAL_SECONDS = 10

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_seesaw(i2c_bus):
    """Initialize the Adafruit Seesaw soil moisture sensor."""
    try:
        return adafruit_seesaw.seesaw.Seesaw(i2c_bus, addr=I2C_ADDRESS)
    except Exception as e:
        print(f"Error initializing Seesaw sensor: {e}")
        return None

def initialize_gpio(pump_pin):
    """Initialize the GPIO pin for the water pump."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pump_pin, GPIO.OUT)
    GPIO.output(pump_pin, GPIO.LOW)  # Ensure pump is initially off

def read_moisture_level(seesaw_sensor):
    """Read the soil moisture level from the sensor."""
    try:
        return seesaw_sensor.moisture_read()
    except Exception as e:
        print(f"Error reading moisture level: {e}")
        return None

def control_water_pump(pump_pin, moisture_level, dry_threshold):
    """Control the water pump based on the moisture level."""
    if moisture_level is not None:
        if moisture_level < dry_threshold:
            GPIO.output(pump_pin, GPIO.HIGH)  # Turn pump ON
            pump_status = "ON"
        else:
            GPIO.output(pump_pin, GPIO.LOW)  # Turn pump OFF
            pump_status = "OFF"
    else:
        pump_status = "UNKNOWN"
    return pump_status

def print_status(moisture_level, pump_status):
    """Print the current moisture level and pump status."""
    print(f"Soil Moisture: {moisture_level}, Pump: {pump_status}")

def main():
    """Main function to run the soil moisture monitoring and water pump control."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    seesaw_sensor = initialize_seesaw(i2c_bus)
    if seesaw_sensor is None:
        i2c_bus.deinit()
        return

    initialize_gpio(PUMP_GPIO_PIN)

    try:
        while True:
            moisture = read_moisture_level(seesaw_sensor)
            pump_state = control_water_pump(PUMP_GPIO_PIN, moisture, DRY_SOIL_THRESHOLD)
            print_status(moisture, pump_state)
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("Exiting program...")
    finally:
        GPIO.output(PUMP_GPIO_PIN, GPIO.LOW)  # Ensure pump is off on exit
        GPIO.cleanup()
        i2c_bus.deinit()
        print("GPIO and I2C resources cleaned up.")

if __name__ == "__main__":
    main()

