import smbus2 as smbus

class I2CDevice:
    """
    A simple class to handle I2C communication on a Raspberry Pi.
    """

    def __init__(self, address, bus_number=1):
        """
        Initializes the I2C device.

        Args:
            address (int): The I2C address of the device.
            bus_number (int): The I2C bus number (default is 1).
        """
        self.address = address
        try:
            self.bus = smbus.SMBus(bus_number)
        except FileNotFoundError:
            raise RuntimeError("I2C bus not found. Check your Raspberry Pi configuration.")
        except Exception as e:
            raise RuntimeError(f"Error accessing I2C bus: {e}")

    def _check_ack(self):
        """
        Checks if the I2C device acknowledges communication.
        """
        try:
            self.bus.read_byte(self.address)  # Quick command to check acknowledgment
            return True
        except OSError:
            return False
        except IOError:
            return False

    def write_byte(self, register, value):
        """
        Writes a byte to a register.

        Args:
            register (int): The register address.
            value (int): The byte value to write.
        """
        try:
            self.bus.write_byte_data(self.address, register, value)
        except OSError as e:
            raise RuntimeError(f"I2C write error: {e}")
        except IOError as e:
            raise RuntimeError(f"I2C write error: {e}")

    def read_byte(self, register):
        """
        Reads a byte from a register.

        Args:
            register (int): The register address.

        Returns:
            int: The byte value read.
        """
        try:
            return self.bus.read_byte_data(self.address, register)
        except OSError as e:
            raise RuntimeError(f"I2C read error: {e}")
        except IOError as e:
            raise RuntimeError(f"I2C read error: {e}")

    def close(self):
        """
        Closes the I2C bus.
        """
        try:
            self.bus.close()
        except Exception as e:
            raise RuntimeError(f"Error closing I2C bus: {e}")

    def __enter__(self):
        """
        Context manager entry.
        """
        if not self._check_ack():
            raise RuntimeError(f"Device at address {self.address} not found.")
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        """
        Context manager exit.
        """
        self.close()
        return False  # Re-raise any exceptions

