#!/usr/bin/python3
# -*- coding: utf-8 -*-

"""
DS1338 Real-Time Clock (RTC) Driver for Raspberry Pi

This module provides a robust and optimized driver for the DS1338 RTC chip.
"""

import smbus2 as smbus
from datetime import datetime, timedelta
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants
DS1338_ADDRESS = 0x68
DS1338_REG_SECONDS = 0x00
DS1338_REG_MINUTES = 0x01
DS1338_REG_HOURS = 0x02
DS1338_REG_DAY = 0x03
DS1338_REG_DATE = 0x04
DS1338_REG_MONTH = 0x05
DS1338_REG_YEAR = 0x06
DS1338_REG_CONTROL = 0x07
DS1338_REG_STATUS = 0x0F  # Added Status Register address

# Bit masks and register values (from datasheet)
RTC_REG_STATUS_OSF = 0x80  # Oscillator Stop Flag
RTC_REG_CONTROL_OUT = 0x04
RTC_REG_CONTROL_SQWE = 0x10
RTC_REG_CONTROL_RS1 = 0x00
RTC_REG_CONTROL_RS2 = 0x20
RTC_REG_CONTROL_RS3 = 0x40
RTC_REG_CONTROL_RS4 = 0x80


def bcd_to_int(bcd_value):
    """Converts a BCD value to an integer."""
    try:
        return (bcd_value >> 4) * 10 + (bcd_value & 0x0F)
    except TypeError:
        logger.exception("Invalid BCD value provided")
        return None


def int_to_bcd(int_value):
    """Converts an integer to BCD format."""
    if not 0 <= int_value <= 99:
        raise ValueError("Integer value must be between 0 and 99 for BCD conversion.")
    return (int_value // 10 << 4) | (int_value % 10)


def _read_register(bus, register, length=1):
    """Reads data from the specified register."""
    try:
        return bus.read_i2c_block_data(DS1338_ADDRESS, register, length)
    except OSError as e:
        logger.error(f"I2C read error: {e}")
        raise


def _write_register(bus, register, data):
    """Writes data to the specified register."""
    try:
        bus.write_i2c_block_data(DS1338_ADDRESS, register, data)
    except OSError as e:
        logger.error(f"I2C write error: {e}")
        raise


class DS1338:
    """Driver for the DS1338 Real-Time Clock (RTC) chip."""

    def __init__(self, twi=1, addr=DS1338_ADDRESS, retry_attempts=3):
        self.bus = smbus.SMBus(twi)
        self.addr = addr
        self.retry_attempts = retry_attempts
        self._verify_connection()  # Check connection on initialization

    def _verify_connection(self):
        """Verifies the RTC connection by reading the status register."""
        for _ in range(self.retry_attempts):
            try:
                _read_register(self.bus, DS1338_REG_STATUS, 1)
                logger.info("DS1338 RTC detected.")
                return
            except OSError:
                logger.warning("DS1338 RTC not found. Retrying...")
        raise RuntimeError(f"Failed to detect DS1338 RTC after {self.retry_attempts} attempts.")


    def _read_with_retry(self, register, length=1):
        """Reads data with retry mechanism."""
        for _ in range(self.retry_attempts):
            try:
                return _read_register(self.bus, register, length)
            except OSError:
                logger.warning("I2C read error. Retrying...")
        raise RuntimeError(f"Failed to read from DS1338 after {self.retry_attempts} attempts.")

    def _write_with_retry(self, register, data):
        """Writes data with retry mechanism."""
        for _ in range(self.retry_attempts):
            try:
                _write_register(self.bus, register, data)
                return
            except OSError:
                logger.warning("I2C write error. Retrying...")
        raise RuntimeError(f"Failed to write to DS1338 after {self.retry_attempts} attempts.")


    def _read_time_register(self, register):
        """Reads and decodes a single time register (BCD)."""
