#!/usr/bin/python3
# -*- coding: utf-8 -*-

"""
DS1338 Real-Time Clock (RTC) Driver for Raspberry Pi

This module provides a driver for the DS1338 RTC chip, utilizing the I2C interface.
It offers functionalities to read and write date and time information to the RTC.
"""

import smbus2 as smbus
from datetime import datetime, timezone
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants for I2C bus and device address
DEFAULT_I2C_BUS = 1
DEFAULT_DEVICE_ADDRESS = 0x68

# Register addresses for the DS1338
REGISTERS = {
    "seconds": 0x00,
    "minutes": 0x01,
    "hours": 0x02,
    "day": 0x03,
    "date": 0x04,
    "month": 0x05,
    "year": 0x06,
    "control": 0x07
}

# Bit masks and values for register fields
CH_BIT = 0x80  # Clock Halt bit
OSC_BIT = 0x80  # Oscillator Stop bit
CONTROL_VALUE = 0x00  # Normal operation


class DS1338Error(Exception):
    """Base class for DS1338 exceptions."""
    pass


class I2CCommunicationError(DS1338Error):
    """Raised when I2C communication fails."""
    pass


class DS1338:
    """Driver class for the DS1338 RTC module."""

    def __init__(self, port: int = DEFAULT_I2C_BUS, address: int = DEFAULT_DEVICE_ADDRESS, debug: bool = False) -> None:
        """
        Initializes the DS1338 driver.

        Args:
            port (int): The I2C bus number (e.g., 1 for /dev/i2c-1). Defaults to 1.
            address (int): The I2C address of the DS1338. Defaults to 0x68.
            debug (bool): Enables debug logging. Defaults to False.
        """
        self.port = port
        self.address = address
        self.debug = debug
        self._bus = None

    def __enter__(self):
        """Context manager entry point, opens the I2C bus."""
        try:
            self._bus = smbus.SMBus(self.port)
            return self
        except Exception as e:
            raise I2CCommunicationError(f"Failed to open I2C bus: {e}") from e

    def __exit__(self, exc_type, exc_val, exc_tb):
        """Context manager exit point, closes the I2C bus."""
        if self._bus:
            self._bus.close()
            self._bus = None


    def _write_register(self, register: str, data: int) -> None:
        """Writes a byte to a specific register."""
        if register not in REGISTERS:
            raise ValueError(f"Invalid register name: {register}")

        try:
            self._bus.write_byte_data(self.address, REGISTERS[register], data)
            if self.debug:
                logger.debug(f"Wrote 0x{data:02X} to register 0x{REGISTERS[register]:02X}")
        except Exception as e:
            raise I2CCommunicationError(f"Failed to write to register 0x{REGISTERS[register]:02X}: {e}") from e


    def _read_register(self, register: str) -> int:
        """Reads a byte from a specific register."""
        if register not in REGISTERS:
            raise ValueError(f"Invalid register name: {register}")

        try:
            data = self._bus.read_byte_data(self.address, REGISTERS[register])
            if self.debug:
                logger.debug(f"Read 0x{data:02X} from register 0x{REGISTERS[register]:02X}")
            return data
        except Exception as e:
            raise I2CCommunicationError(f"Failed to read from register 0x{REGISTERS[register]:02X}: {e}") from e

    def _bcd_to_int(self, bcd: int) -> int:
        """Converts a BCD value to an integer."""
        return (bcd >> 4) * 10 + (bcd & 0x0F)

    def _int_to_bcd(self, integer: int) -> int:
        """Converts an integer to BCD format."""
        if not 0 <= integer <= 99:
            raise ValueError("Integer must be between 0 and 99 for BCD conversion.")
        return (integer // 10 << 4) | (integer % 10)


    def read_all(self) -> tuple[int, int, int, int, int, int, int]:
        """Reads all time and date registers."""
        try:
            year = self._bcd_to_int(self._read_register("year"))
            month = self._bcd_to_int(self._read_register("month"))
            date = self._bcd_to_int(self._read_register("date"))
            day = self._bcd_to_int(self._read_register("day"))
            hours = self._bcd_to_int(self._read_register("hours") & 0x3F)  # Ensure 24-hour mode
            minutes = self._bcd_to_int(self._read_register("minutes"))
            seconds = self._bcd_to_int(self._read_register("seconds") & 0x7F)  # Clear CH bit
            return year, month, date, day, hours, minutes, seconds
        except I2CCommunicationError as e:
            raise


    def read_datetime(self, century: int = 21) -> datetime:
        """Reads the date and time and returns a datetime object."""
        try:
            year, month, date, _, hours, minutes, seconds = self.read_all()
            year = (century - 1) * 100 + year  # Correct year calculation
            return datetime(year, month, date, hours, minutes, seconds, tzinfo=timezone.utc)
        except ValueError as e:
            raise DS1338Error(f"Invalid time/date data read: {e}") from e
        except I2CCommunicationError as e:
            raise


    def write_all(self, year: int, month: int, date: int, day: int, hours: int, minutes: int, seconds: int) -> None:
        """Writes all time and date registers."""

        for value, register in [(seconds, "seconds"), (minutes, "minutes"), (hours, "hours"),
                                 (day, "day"), (date, "date"), (month, "month"), (self._int_to_bcd(year % 100), "year")]: # Year is written as the last two digits
            self._write_register(register, self._int_to_bcd(value))


        # Ensure CH bit is cleared and 24-hour mode is enabled
        self._write_register("seconds", self._read_register("seconds") & ~CH_BIT)
        self._write_register("hours", self._read_register("hours") & ~0x40)  # Clear 12/24 bit


    def write_datetime(self, dt: datetime) -> None:
        """Writes the date and time from a datetime object."""
        try:
            if not dt.tzinfo:
                raise ValueError("Datetime object must have timezone information.")
            self.write_all(dt.year % 100, dt.month, dt.day, dt.isoweekday(), dt.hour, dt.minute, dt.second)
        except ValueError as e:
            raise DS1338Error(f"Invalid datetime object: {e}") from e
        except I2CCommunicationError as e:
            raise


    def write_now(self) -> None:
        """Writes the current Raspberry Pi time to the RTC."""
        try:
            self.write_datetime(datetime.now(timezone.utc))
        except DS1338Error as e:
            raise


if __name__ == "__main__":
    try:
        with DS1338(debug=True) as rtc:
            current = rtc.read_datetime()
            logger.info(f"Current RTC time: {current}")
    except I2CCommunicationError as e:
        logger.error(f"I2C communication error: {e}")
    except DS1338Error as e:
        logger.error(f"DS1338 error: {e}")

