#!/usr/bin/env python3

"""
Flask-based web API for interacting with a USB serial device and a data store.

This script provides a RESTful API to communicate with a device connected via USB serial
and manage a simple in-memory data store. It is designed for use with a Raspberry Pi.

Author: Gemini
Version: 1.0
Date: 2024-02-29
"""

import json
import time
import signal
import threading
from functools import wraps

from flask import Flask, Response, request, jsonify, abort
import serial

app = Flask(__name__)

# Constants
DEFAULT_SERIAL_PORT = '/dev/ttyUSB0'
DEFAULT_BAUDRATE = 9600
DATA_STORE = [
    {"id": 1, "name": "Item 1", "done": False},
    {"id": 2, "name": "Item 2", "done": True}
]
SERIAL_PORT = None  # Global variable for serial port
SERIAL_LOCK = threading.Lock()  # Lock for serial port access


class SerialCommunicator:
    """
    Manages serial communication with the USB device.
    """

    def __init__(self, port=DEFAULT_SERIAL_PORT, baudrate=DEFAULT_BAUDRATE):
        """
        Initializes the SerialCommunicator.

        Args:
            port (str): The serial port to use.
            baudrate (int): The baud rate for serial communication.
        """
        self.port = port
        self.baudrate = baudrate
        self.ser = None

    def open(self):
        """
        Opens the serial port.

        Returns:
            bool: True if the port was opened successfully, False otherwise.
        """
        try:
            self.ser = serial.Serial(self.port, self.baudrate, timeout=1)  # 1 second timeout
            return True
        except serial.SerialException as e:
            print(f"Error opening serial port: {e}")
            return False

    def send(self, cmd):
        """
        Sends a command to the USB device.

        Args:
            cmd (str): The command to send.

        Returns:
            int: The number of bytes written, or -1 on error.
        """
        if not self.ser:
            print("Serial port not open.")
            return -1
        try:
            cmd = cmd.encode('utf-8')
            self.ser.write(cmd)
            self.ser.flush()
            return len(cmd)
        except serial.SerialException as e:
            print(f"Error sending command: {e}")
            return -1

    def receive_line(self):
        """
        Receives a line of data from the USB device.

        Returns:
            str: The received line, or None on timeout or error.
        """
        if not self.ser:
            print("Serial port not open.")
            return None
        try:
            line = self.ser.readline().decode('utf-8', errors='ignore').strip()
            return line
        except serial.SerialException as e:
            print(f"Error receiving data: {e}")
            return None

    def close(self):
        """
        Closes the serial port.
        """
        if self.ser:
            self.ser.close()
            self.ser = None


# Initialize SerialCommunicator
serial_communicator = SerialCommunicator()


def with_serial_comm(func):
    """
    Decorator to manage serial port lifecycle.
    """

    @wraps(func)
    def wrapper(*args, **kwargs):
        global serial_communicator
        with SERIAL_LOCK:
            if not serial_communicator.ser:
                if not serial_communicator.open():
                    return Response("Failed to open serial port", status=500, mimetype='text/plain')
            try:
                return func(*args, **kwargs)
            finally:
                # No need to close in the decorator, it's handled by the SerialCommunicator
                pass

    return wrapper


def get_data_store():
    """
    Returns the data store.

    Returns:
        list: The data store.
    """
    return DATA_STORE


def get_item(item_id):
    """
    Retrieves an item from the data store by ID.

    Args:
        item_id (int): The ID of the item to retrieve.

    Returns:
        dict: The item, or None if not found.
    """
    for item in get_data_store():
        if item['id'] == item_id:
            return item
    return None


@app.route('/version', methods=['GET'])
@with_serial_comm
def get_device_version():
    """
    Retrieves the device version information.

    Returns:
        Response: The device version information or an error message.
    """
    try:
        serial_communicator.send('*IDN?\n')
        response = serial_communicator.receive_line()
        if response:
            return Response(response, mimetype='text/plain')
        else:
            return Response("Timeout or error receiving version information", status=504, mimetype='text/plain')
    except Exception as e:
        print(f"Error getting device version: {e}")
        return Response(str(e), status=502, mimetype='text/plain')


@app.route('/data', methods=['GET'])
def get_all_data():
    """
    Retrieves all data from the data store.

    Returns:
        Response: JSON representation of the data store.
    """
    return jsonify(get_data_store())


@app.route('/data/<int:item_id>', methods=['GET'])
def get_data_item(item_id):
    """
    Retrieves a specific item from the data store.

    Args:
        item_id (int): The ID of the item to retrieve.

    Returns:
        Response: JSON representation of the item, or 404 if not found.
    """
    item = get_item(item_id)
    if item:
        return jsonify(item)
    else:
        return Response("Item not found", status=404, mimetype='text/plain')


@app.route('/data', methods=['POST'])
def create_data_item():
    """
    Creates a new item in the data store.

    Returns:
        Response: JSON representation of the created item, or 400 if invalid data.
    """
    try:
        data = request.get_json()
        if not data or 'name' not in data:
            return Response("Invalid data: 'name' field is required", status=400, mimetype='text/plain')

        new_id = max(item['id'] for item in get_data_store()) + 1 if get_data_store() else 1
        new_item = {
            'id': new_id,
            'name': data['name'],
            'done': data.get('done', False)  # Use .get() with default value
        }

        if not isinstance(new_item['done'], bool):
            return Response("Invalid data: 'done' field must be a boolean", status=400, mimetype='text/plain')

        get_data_store().append(new_item)
        return jsonify(new_item), 201

    except (TypeError, ValueError) as e:
        print(f"Invalid JSON data: {e}")
        return Response("Invalid JSON data", status=400, mimetype='text/plain')


def shutdown_server():
    """
    Shuts down the Flask development server.
    """
    func = request.environ.get('werkzeug.server.shutdown')
    if func is None:
        raise RuntimeError('Not running with the Werkzeug Server')
    func()


@app.route('/shutdown', methods=['POST'])
def shutdown():
    """
    Shuts down the server.

    Returns:
        Response: Shutdown message.
    """
    shutdown_server()
    return 'Server shutting down...'


def signal_handler(sig, frame):
    """
    Handles signals for graceful shutdown.

    Args:
        sig: The signal received.
        frame: The current stack frame.
    """
    print('You pressed Ctrl+C!')
    with SERIAL_LOCK:
        if serial_communicator.ser:
            serial_communicator.close()
    shutdown_server()


if __name__ == '__main__':
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        app.run(debug=False, host='0.0.0.0')
    finally:
        with SERIAL_LOCK:
            if serial_communicator.ser:
                serial_communicator.close()

