from flask import Flask, Response, request, jsonify, abort
import json
import time
import serial
from typing import Union, Callable, Any, Dict, List

app = Flask(__name__)
app.config['JSONIFY_MIMETYPE'] = 'application/json'

# Type aliases for clarity
JsonResponse = Response
ErrorResponse = Response
MaybeSerial = Union[serial.Serial, None]

# --- Utility Functions ---

def with_serial_port(device: str, baudrate: int, 
                     func: Callable[[serial.Serial], Any]) -> Any:
    """
    Opens and closes the serial port, executing the provided function.
    Handles serial port errors.
    """
    try:
        with serial.Serial(device, baudrate=baudrate, timeout=1) as ser:
            return func(ser)
    except serial.SerialException as e:
        print(f"Serial port error: {e}")
        return None

def format_scpi_response(response: bytes) -> str:
    """Formats the SCPI response for HTML display."""
    return f'<pre>{response.decode("utf-8", "ignore").replace("\\n", "<br>")}</pre>'

# --- Data Store ---

def get_store() -> List[Dict[str, Union[int, str, bool]]]:
    """Returns the in-memory data store."""
    return [
        {"id": 1, "name": "CHIPS", "done": False},
        {"id": 2, "name": "garden", "done": False}
    ]

def get_next_id(store: List[Dict[str, Union[int, str, bool]]]) -> int:
    """Returns the next available ID for the data store."""
    return max(item["id"] for item in store) + 1 if store else 1

# --- Route Handlers ---

@app.route('/version')
def get_instrument_version() -> JsonResponse:
    """
    Retrieves the instrument version via SCPI.

    Sends the '*IDN?' command to the instrument and returns the response
    formatted as HTML. Handles potential serial port errors.
    """
    def query_instrument(ser: serial.Serial) -> bytes:
        ser.write(b'*IDN?\n')
        time.sleep(0.1)  # Allow time for response
        return ser.read_all()

    result = with_serial_port('/dev/ttyUSB0', 9600, query_instrument)

    if result:
        return Response(format_scpi_response(result), mimetype='text/html')
    else:
        return Response("Error communicating with the instrument.", status=503, mimetype='text/plain')


@app.route('/getdata')
def get_data() -> JsonResponse:
    """Returns the current data store as JSON."""
    return jsonify(get_store())


@app.route('/getset/<int:item_id>')
def get_specific_item(item_id: int) -> Union[JsonResponse, ErrorResponse]:
    """
    Retrieves a specific item from the data store by ID.

    Returns a 404 error if the item is not found.
    """
    store = get_store()
    item = next((item for item in store if item['id'] == item_id), None)
    if item:
        return jsonify(item)
    else:
        return abort(404)


@app.route('/getpost/<int:item_id>/<name>')
def post_new_item(item_id: int, name: str) -> JsonResponse:
    """
    Adds a new item to the data store.

    The 'item_id' parameter is ignored, and a new ID is generated.
    """
    store = get_store()
    new_id = get_next_id(store)
    new_item = {
        "id": new_id,
        "name": name,
        "done": False
    }
    store.append(new_item)
    return jsonify(store)


@app.route('/postjson', methods=['POST'])
def handle_post_json() -> Union[JsonResponse, ErrorResponse]:
    """
    Handles JSON POST requests.

    Supports both 'application/json' and 'application/x-www-form-urlencoded'
    content types.
    """
    store = get_store()
    new_id = get_next_id(store)

    if request.is_json:
        try:
            data = request.get_json()
            if not isinstance(data, dict):
                raise ValueError("Invalid JSON format: expected an object")
        except json.JSONDecodeError:
            return abort(400, "Invalid JSON data")
        except ValueError as e:
            return abort(400, str(e))
    else:
        data = request.form.to_dict()

    name = data.get('name', '')
    if not isinstance(name, str):
        try:
            name = str(name)
        except (TypeError, ValueError):
            return abort(400, "Invalid 'name' value: could not convert to string")

    done = data.get('done', 'False').lower() in ('true', '1', 'yes')
    if not isinstance(done, bool):
        try:
            done = bool(data.get('done', '').lower() in ('true', '1', 'yes'))
        except (TypeError, ValueError):
            return abort(400, "Invalid 'done' value: could not convert to boolean")

    new_item = {
        "id": new_id,
        "name": name,
        "done": done
    }
    store.append(new_item)
    return jsonify(store)


@app.route('/postreturn')
def handle_post_return() -> Union[JsonResponse, ErrorResponse]:
    """
    Handles POST requests with 'application/x-www-form-urlencoded' content type.

    Returns the posted data as JSON.
    """
    data = request.form.to_dict()
    return jsonify(data)


# --- Main Application ---

if __name__ == '__main__':
    app.run(debug=True, host='0.0.0.0')

