import serial
import time

# Define constants for serial connection
BLUETOOTH_DEVICE = "/dev/rfcomm4"
BLUETOOTH_BAUD_RATE = 38400
COMMAND_PREFIX = 'X'
NEWLINE_CHAR = '\n'

def create_serial_connection(device, baudrate):
    """Establishes a serial connection to the Bluetooth device."""
    try:
        connection = serial.Serial(device, baudrate)
        return connection
    except serial.SerialException as e:
        raise RuntimeError(f"Failed to open serial port: {e}")

def format_command(command_string):
    """Formats the command string for transmission."""
    return f"{COMMAND_PREFIX}{command_string}{NEWLINE_CHAR}".encode("utf-8")

def send_command(connection, command):
    """Sends a formatted command over the serial connection."""
    try:
        connection.write(command)
        time.sleep(0.1)  # Add a small delay to avoid overwhelming the device
    except serial.SerialException as e:
        raise RuntimeError(f"Failed to write to serial port: {e}")

def main():
    """Main function to handle user input and send commands."""
    serial_connection = None
    try:
        serial_connection = create_serial_connection(BLUETOOTH_DEVICE, BLUETOOTH_BAUD_RATE)
        while True:
            try:
                user_input = input("Enter command (or 'exit' to quit): ")
                if user_input.lower() == "exit":
                    break
                formatted_command = format_command(user_input)
                send_command(serial_connection, formatted_command)
            except RuntimeError as e:
                print(f"Error: {e}")
                break
            except KeyboardInterrupt:
                print("\nExiting program.")
                break
    except RuntimeError as e:
        print(f"Fatal Error: {e}")
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial connection closed.")

if __name__ == "__main__":
    main()

